/// ===============================================================
/// Color Wheel Bottom Sheet
/// ===============================================================

class _AppColorWheelSheet extends StatefulWidget {
  const _AppColorWheelSheet({
    required this.title,
    required this.subtitle,
    required this.initial,
    required this.onApply,
  });

  final String title;
  final String subtitle;
  final Color initial;
  final Future<void> Function(Color color) onApply;

  @override
  State<_AppColorWheelSheet> createState() => _AppColorWheelSheetState();
}

class _AppColorWheelSheetState extends State<_AppColorWheelSheet> {
  late HSVColor _hsv;
  bool _isSaving = false;

  @override
  void initState() {
    super.initState();
    _hsv = HSVColor.fromColor(widget.initial);
  }

  Future<void> _apply() async {
    if (_isSaving) return;

    setState(() {
      _isSaving = true;
    });

    try {
      await widget.onApply(_hsv.toColor());

      if (!mounted) return;

      Navigator.of(context).pop();
    } finally {
      if (mounted) {
        setState(() {
          _isSaving = false;
        });
      }
    }
  }

  void _updateColor(HSVColor value) {
    setState(() {
      _hsv = value;
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colors = theme.colorScheme;
    final selectedColor = _hsv.toColor();

    final bottomInset = MediaQuery.viewInsetsOf(context).bottom;

    return Directionality(
      textDirection: TextDirection.rtl,
      child: SafeArea(
        top: false,
        child: Material(
          color: colors.surface,
          elevation: 12,
          clipBehavior: Clip.antiAlias,
          borderRadius: const BorderRadius.vertical(
            top: Radius.circular(32),
          ),
          child: SingleChildScrollView(
            padding: EdgeInsets.fromLTRB(
              20,
              12,
              20,
              20 + bottomInset,
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                _SheetDragHandle(
                  color: colors.outlineVariant,
                ),

                const SizedBox(height: 22),

                _ColorSheetHeader(
                  title: widget.title,
                  subtitle: widget.subtitle,
                  color: selectedColor,
                ),

                const SizedBox(height: 24),

                _ColorPickerCard(
                  hsv: _hsv,
                  selectedColor: selectedColor,
                  onChanged: _updateColor,
                ),

                const SizedBox(height: 18),

                _ColorPreview(
                  color: selectedColor,
                  colors: colors,
                ),

                const SizedBox(height: 20),

                _ApplyColorButton(
                  color: selectedColor,
                  isSaving: _isSaving,
                  onPressed: _apply,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}


