class _ColorWheel extends StatelessWidget {
  const _ColorWheel({
    required this.hsv,
    required this.onChanged,
  });

  final HSVColor hsv;
  final ValueChanged<HSVColor> onChanged;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final size = math.min(
          constraints.maxWidth,
          constraints.maxHeight,
        );

        return Center(
          child: SizedBox(
            width: size,
            height: size,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,

              onPanDown: (details) {
                _handlePosition(
                  details.localPosition,
                  size,
                );
              },

              onPanUpdate: (details) {
                _handlePosition(
                  details.localPosition,
                  size,
                );
              },

              child: CustomPaint(
                painter: _ColorWheelPainter(hsv),
                size: Size.square(size),
              ),
            ),
          ),
        );
      },
    );
  }

  void _handlePosition(
      Offset position,
      double size,
      ) {
    final center = Offset(
      size / 2,
      size / 2,
    );

    final offset = position - center;
    final radius = size / 2;
    final distance = offset.distance;

    // حصر المؤشر داخل حدود الدائرة
    final saturation = (distance / radius).clamp(0.0, 1.0);

    // atan2 في إحداثيات الشاشة يبدأ من الجهة اليمنى
    // ويزداد مع اتجاه عقارب الساعة، وهو نفس اتجاه SweepGradient
    var hue = math.atan2(
      offset.dy,
      offset.dx,
    ) *
        180 /
        math.pi;

    if (hue < 0) {
      hue += 360;
    }

    onChanged(
      HSVColor.fromAHSV(
        1.0,
        hue,
        saturation,
        hsv.value,
      ),
    );
  }
}

class _ColorWheelPainter extends CustomPainter {
  _ColorWheelPainter(this.hsv);

  final HSVColor hsv;

  static const List<Color> _wheelColors = [
    Color(0xFFFF0000), // Red
    Color(0xFFFFFF00), // Yellow
    Color(0xFF00FF00), // Green
    Color(0xFF00FFFF), // Cyan
    Color(0xFF0000FF), // Blue
    Color(0xFFFF00FF), // Magenta
    Color(0xFFFF0000), // Red
  ];

  @override
  void paint(
      Canvas canvas,
      Size size,
      ) {
    final center = Offset(
      size.width / 2,
      size.height / 2,
    );

    final radius = math.min(
      size.width,
      size.height,
    ) /
        2;

    final wheelRect = Rect.fromCircle(
      center: center,
      radius: radius,
    );

    // ------------------------------------------------------------
    // 1. رسم ألوان Hue
    //
    // لا نستخدم GradientRotation هنا.
    // يبدأ اللون الأحمر من الجهة اليمنى، وهي نفس نقطة حساب atan2.
    // ------------------------------------------------------------

    final huePaint = Paint()
      ..shader = const SweepGradient(
        colors: _wheelColors,
        stops: [
          0.0,
          1 / 6,
          2 / 6,
          3 / 6,
          4 / 6,
          5 / 6,
          1.0,
        ],
      ).createShader(wheelRect);

    canvas.drawCircle(
      center,
      radius,
      huePaint,
    );

    // ------------------------------------------------------------
    // 2. إضافة التشبع Saturation
    //
    // المركز أبيض = تشبع 0
    // الحافة = تشبع 1
    // ------------------------------------------------------------

    final saturationPaint = Paint()
      ..shader = RadialGradient(
        colors: [
          Colors.white,
          Colors.white.withOpacity(0.0),
        ],
        stops: const [
          0.0,
          1.0,
        ],
      ).createShader(wheelRect);

    canvas.drawCircle(
      center,
      radius,
      saturationPaint,
    );

    // ------------------------------------------------------------
    // 3. تطبيق قيمة السطوع Value على كامل الدائرة
    //
    // عند value = 1 لا يوجد تعتيم.
    // عند value = 0 تصبح الدائرة سوداء.
    // ------------------------------------------------------------

    final brightness = hsv.value.clamp(0.0, 1.0);
    final darkness = 1.0 - brightness;

    if (darkness > 0) {
      final brightnessPaint = Paint()
        ..color = Colors.black.withOpacity(darkness);

      canvas.drawCircle(
        center,
        radius,
        brightnessPaint,
      );
    }

    // ------------------------------------------------------------
    // 4. رسم مؤشر اللون المختار
    // ------------------------------------------------------------

    final angle = hsv.hue * math.pi / 180;
    final selectedRadius = radius * hsv.saturation;

    final selectedPosition = Offset(
      center.dx + math.cos(angle) * selectedRadius,
      center.dy + math.sin(angle) * selectedRadius,
    );

    // ظل خلف المؤشر حتى يكون واضحًا على جميع الألوان
    final shadowPaint = Paint()
      ..color = Colors.black.withOpacity(.28)
      ..maskFilter = const MaskFilter.blur(
        BlurStyle.normal,
        4,
      );

    canvas.drawCircle(
      selectedPosition,
      16,
      shadowPaint,
    );

    // الحلقة الخارجية
    final outerPaint = Paint()
      ..color = Colors.white
      ..style = PaintingStyle.stroke
      ..strokeWidth = 4;

    canvas.drawCircle(
      selectedPosition,
      14,
      outerPaint,
    );

    // لون المؤشر الداخلي
    final innerPaint = Paint()
      ..color = hsv.toColor()
      ..style = PaintingStyle.fill;

    canvas.drawCircle(
      selectedPosition,
      10,
      innerPaint,
    );

    // نقطة صغيرة داخل المؤشر لتحسين الوضوح
    final centerPaint = Paint()
      ..color = _getContrastColor(hsv.toColor());

    canvas.drawCircle(
      selectedPosition,
      3,
      centerPaint,
    );
  }

  @override
  bool shouldRepaint(
      covariant _ColorWheelPainter oldDelegate,
      ) {
    return oldDelegate.hsv != hsv;
  }

  Color _getContrastColor(Color color) {
    final brightness = ThemeData.estimateBrightnessForColor(color);

    return brightness == Brightness.dark
        ? Colors.white
        : Colors.black.withOpacity(.75);
  }
}


