/// Returns a readable foreground color.
Color _onColor(Color color) {
  final brightness = ThemeData.estimateBrightnessForColor(color);

  return brightness == Brightness.dark
      ? Colors.white
      : Colors.black87;
}


Future<String> translateSubject(BuildContext context, String subject) async {
  try {
    // جلب اللغة المختارة من التطبيق
    final lang = UniSpaceApp.of(context)._locale.languageCode;

    // إذا كانت العربية → نعيد النص كما هو
    if (lang == 'ar') return subject;

    // ترجمة للنص حسب اللغة المختارة
    var translation = await translator.translate(subject, to: lang);
    return translation.text;
  } catch (e) {
    // fallback عند حدوث خطأ
    return subject;
  }
}
final translator = GoogleTranslator(); // كائن الترجمة
class AutoTranslate {
  static final translator = GoogleTranslator();

  static Future<String> tr(BuildContext context, String text) async {
    final lang = UniSpaceApp.of(context)._locale.languageCode;

    // إذا كانت نفس اللغة → لا حاجة للترجمة
    if (lang == 'ar') return text;

    try {
      final translation = await translator.translate(text, to: lang);
      return translation.text;
    } catch (_) {
      return text; // إذا فشلت الترجمة
    }
  }
}
class UniSpaceApp extends StatefulWidget {
  const UniSpaceApp({
    super.key,
    required this.initialThemeMode,
    required this.initialLocale,
  });

  final ThemeMode initialThemeMode;
  final Locale initialLocale;

  static _UniSpaceAppState of(BuildContext context) =>
      context.findAncestorStateOfType<_UniSpaceAppState>()!;

  @override
  State<UniSpaceApp> createState() => _UniSpaceAppState();
}

class _UniSpaceAppState extends State<UniSpaceApp> {
  ThemeMode _themeMode = ThemeMode.system;
  Locale _locale = const Locale('en');

  Color _primaryColor = AppPrimary.seed;
  static const _kPrimary = 'pref_primaryColor';

  Color get primaryColor => _primaryColor;

  static const Color _defaultPrimary = Color(0xFF30475E);

  Future<void> resetAccentColors() async {
    _tealColor = kDefaultTeal;
    _primaryColor = _defaultPrimary;
    AppTeal.apply(_tealColor);
    AppPrimary.apply(_primaryColor);
    setState(() {});

    final p = await SharedPreferences.getInstance();
    await p.remove(_kTeal);
    await p.remove(_kPrimary);
  }

  Future<void> setTealColor(Color c) async {
    _tealColor = c;
    AppTeal.apply(c);
    setState(() {});
    final p = await SharedPreferences.getInstance();
    await p.setInt(_kTeal, c.value);
  }

  Future<void> setPrimaryColor(Color c) async {
    _primaryColor = c;
    AppPrimary.apply(c);
    setState(() {});
    final p = await SharedPreferences.getInstance();
    await p.setInt(_kPrimary, c.value);
  }
  static const _kTheme = 'pref_themeMode';
  static const _kLocale = 'pref_locale';
  Color _tealColor = kDefaultTeal;
  static const _kTeal = 'pref_tealColor';

  Color get tealColor => _tealColor;


  @override
  void initState() {
    super.initState();
    _themeMode = widget.initialThemeMode;
    _locale = widget.initialLocale;
    _restorePrefs();
  }

  Future<void> _restorePrefs() async {
    final p = await SharedPreferences.getInstance();
    final themeIdx = p.getInt(_kTheme);
    final lang = p.getString(_kLocale);

    final tealVal = p.getInt('pref_tealColor');
    if (tealVal != null) AppTeal.apply(Color(tealVal));
    final primaryVal = p.getInt(_kPrimary);
    if (primaryVal != null) {
      _primaryColor = Color(primaryVal);
      AppPrimary.apply(_primaryColor);
    }
    if (tealVal != null) {
      _tealColor = Color(tealVal);
      AppTeal.apply(_tealColor);
    }
    if (themeIdx != null &&
        themeIdx >= 0 &&
        themeIdx < ThemeMode.values.length) {
      _themeMode = ThemeMode.values[themeIdx];
    }
    if (lang != null && lang.isNotEmpty) {
      _locale = Locale(lang);
    }
    if (mounted) setState(() {});
  }

  Future<void> setThemeMode(ThemeMode m) async {
    setState(() => _themeMode = m);
    final p = await SharedPreferences.getInstance();
    await p.setInt(_kTheme, m.index);
  }

  Future<void> setLocale(Locale l) async {
    setState(() => _locale = l);
    final p = await SharedPreferences.getInstance();
    await p.setString(_kLocale, l.languageCode);
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      navigatorKey: unispaceNavigatorKey,
      title: 'UniSpace',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.light,
      darkTheme: AppTheme.dark,
      themeMode: _themeMode,
      locale: _locale,
      localizationsDelegates: [
        S.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: S.delegate.supportedLocales,
      builder: (context, child) {
        return LoginAlertWatcher(
          navigatorKey: unispaceNavigatorKey,
          child: ValueListenableBuilder<SettingsData>(
            valueListenable: AppSettings.instance.notifier,
            builder: (context, settings, _) {
              return MediaQuery(
                data: MediaQuery.of(context).copyWith(
                  textScaler: TextScaler.linear(settings.fontScale.scale),
                ),
                child: child ?? const SizedBox.shrink(),
              );
            },
          ),
        );
      },
      home: const AuthGate(),
    );
  }
}

// ============================================================================
// Global End Drawer — يعمل فعليًا (مظهر/لغة/إعادة كلمة السر/روابط)
// ============================================================================
class HomeShell extends StatefulWidget {
  const HomeShell({super.key});
  @override
  State<HomeShell> createState() => _HomeShellState();
}

class _HomeShellState extends State<HomeShell> with WidgetsBindingObserver {
  int _selectedIndex = 0;

  late final List<Widget> _tabPages;
  StreamSubscription<Uri>? _linkSub;
  final _appLinks = deep_links.AppLinks();
  bool _barVisible = true;
  double _lastScrollPixels = 0;

  bool _onScroll(ScrollNotification n) {
    if (n.metrics.axis != Axis.vertical) return false;
    if (n is! ScrollUpdateNotification) return false;

    final delta = n.scrollDelta ?? (n.metrics.pixels - _lastScrollPixels);
    _lastScrollPixels = n.metrics.pixels;

    // في أعلى الصفحة → أظهر الشريط دائمًا
    if (n.metrics.pixels <= 8) {
      if (!_barVisible) setState(() => _barVisible = true);
      return false;
    }

    // تمرير لأسفل → أخفِ الشريط
    if (delta > 6 && _barVisible) {
      setState(() => _barVisible = false);
    }
    // تمرير لأعلى (تنزيل الشاشة) → أظهر الشريط
    else if (delta < -6 && !_barVisible) {
      setState(() => _barVisible = true);
    }

    return false; // لا تمنع التمرير
  }
  late final Widget _home;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initializeCurrentSession();
    setUserPresence(online: true);
    _home = CommunityScreen(onOpenDrawer: _openEndDrawer);
    _initDeepLinks();
  }
  Future<void> _initDeepLinks() async {
    try {
      final initial = await _appLinks.getInitialLink();
      if (initial != null) _handleIncomingLink(initial);
    } catch (e) {
      debugPrint('Initial link error: $e');
    }

    _linkSub = _appLinks.uriLinkStream.listen(
      _handleIncomingLink,
      onError: (e) => debugPrint('Link stream error: $e'),
    );
  }

  void _handleIncomingLink(Uri uri) {
    if (uri.scheme != 'unispace') return;
    if (uri.host != 'post') return;

    final postId = uri.pathSegments.isNotEmpty
        ? uri.pathSegments.first
        : uri.path.replaceFirst('/', '');

    if (postId.isEmpty) return;
    debugPrint('Open post from link: $postId');
    _openPostById(postId);
  }

  Future<void> _openPostById(String postId) async {
    try {
      final data = await _readAuthorizedPostData(postId);
      final post = _Post.fromData(postId, data);
      if (!mounted) return;

      // انتقل لتبويب المجتمع ثم افتح المنشور


      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => CommentsScreen(post: post),
        ),
      );
    } catch (e) {
      debugPrint('Open post failed: $e');
    }
  }
  Future<void> _initializeCurrentSession() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    await SessionService.instance.initSession(user.uid);
  }

  Future<void> _touchCurrentSession() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    final revoked = await SessionService.instance.isCurrentSessionRevoked(user.uid);
    if (revoked) {
      if (kDebugMode) debugPrint('[Auth] session revoked -> signOut');
      await AuthSessionService.signOutFully();
      return;
    }
    await SessionService.instance.updateLastSeen(user.uid);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    switch (state) {
      case AppLifecycleState.resumed:
        _touchCurrentSession();
        setUserPresence(online: true);
        break;
      case AppLifecycleState.inactive:
      case AppLifecycleState.hidden:
      case AppLifecycleState.paused:
      case AppLifecycleState.detached:
        setUserPresence(online: false);
        break;
    }
  }

  @override
  void dispose() {
    _linkSub?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    setUserPresence(online: false);
    super.dispose();
  }

  void _openEndDrawer() {
    showGeneralDialog(
      context: context,
      barrierDismissible: true,
      barrierLabel: MaterialLocalizations.of(context).modalBarrierDismissLabel,
      transitionDuration: const Duration(milliseconds: 250),
      pageBuilder: (context, animation, secondaryAnimation) {
        return Align(
          alignment: Alignment.centerRight,
          child: Material(
            elevation: 8,
            child: SizedBox(
              width: MediaQuery.of(context).size.width * 0.85,
              height: MediaQuery.of(context).size.height,
              child: const AppEndDrawer(),
            ),
          ),
        );
      },
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        return SlideTransition(
          position: Tween<Offset>(
            begin: const Offset(1, 0),
            end: Offset.zero,
          ).animate(CurvedAnimation(
            parent: animation,
            curve: Curves.easeOut,
          )),
          child: child,
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: _home,
    );
  }
}



// ============================================================================
// Auth Gate + SignIn
// ============================================================================
class AuthGate extends StatefulWidget {
  const AuthGate({super.key});

  @override
  State<AuthGate> createState() => _AuthGateState();
}

class _AuthGateState extends State<AuthGate> {
  User? _lastAuthUser;
  bool _blockingSignOut = false;
  Stream<DocumentSnapshot<Map<String, dynamic>>>? _userDocStream;
  String? _userDocStreamUid;

  Stream<DocumentSnapshot<Map<String, dynamic>>> _statusStreamFor(String uid) {
    if (_userDocStream == null || _userDocStreamUid != uid) {
      _userDocStreamUid = uid;
      _userDocStream = FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .snapshots();
    }
    return _userDocStream!;
  }

  Future<bool> _isTwoFactorRequired(User user) async {
    final profile =
    await FirebaseFirestore.instance.collection('users').doc(user.uid).get(const GetOptions(source: Source.server));
    final enabled = profile.data()?['twoFactorEnabled'] as bool? ?? false;
    if (!enabled) return false;
    final token = await user.getIdTokenResult();
    final firebase = token.claims?['firebase'];
    if (firebase is Map && firebase['sign_in_second_factor'] == 'totp') return false;
    return !(await TwoFactorService.instance.isCurrentSessionVerified(user));
  }

  Future<void> _blockAndSignOut(String reason) async {
    if (_blockingSignOut) return;
    _blockingSignOut = true;
    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user != null) {
        await SessionService.instance.revokeCurrentSession(user.uid);
      }
      await AuthSessionService.signOutFully();
      if (kDebugMode) debugPrint('[AuthGate] blocked: $reason');
    } finally {
      _blockingSignOut = false;
    }
  }

  void _refreshStatus() {
    if (!mounted) return;
    setState(() {});
  }

  Widget _routeAuthenticated(User user, bool isPasswordUser) {
    return AuthSecurityCheck(
      key: ValueKey('security-check:${user.uid}:${TwoFactorService.instance.authRefresh.value}'),
      check: () => _isTwoFactorRequired(user),
      challengeBuilder: (_) => TwoFactorOtpScreen(email: user.email ?? ''),
      child: const HomeShell(),
    );
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<int>(
      valueListenable: TwoFactorService.instance.authRefresh,
      builder: (_, __, ___) {
        return StreamBuilder<User?>(
          stream: FirebaseAuth.instance.authStateChanges(),
          builder: (ctx, snap) {
            if (Firebase.apps.isEmpty) {
              return const Scaffold(
                body: Center(
                  child: Text('تعذر تشغيل Firebase. أعد فتح التطبيق.'),
                ),
              );
            }
            if (snap.connectionState == ConnectionState.waiting) {
              return const Scaffold(
                body: Center(child: CircularProgressIndicator()),
              );
            }

            if (!identical(_lastAuthUser, snap.data)) {
              _lastAuthUser = snap.data;
              if (kDebugMode) {
                debugPrint(
                  '[AuthGate] authStateChanges user=${snap.data?.uid ?? 'null'}',
                );
              }
            }

            if (!snap.hasData) {
              _userDocStream = null;
              _userDocStreamUid = null;
              return const SignInScreen();
            }

            final user = snap.data!;
            final isPasswordUser = user.providerData
                .any((info) => info.providerId == 'password');
// if (isPasswordUser && !user.emailVerified) {
            //   return VerifyEmailScreen(
            //     key: ValueKey('verify_${user.uid}'),
            //     email: user.email ?? '',
            //     password: '',
            //   );
            // }
            return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
              stream: _statusStreamFor(user.uid),
              builder: (context, statusSnap) {
                if (statusSnap.hasError) {
                  debugPrint('AuthGate user doc: ${statusSnap.error}');
                  return _routeAuthenticated(user, isPasswordUser);
                }

                final doc = statusSnap.data;
                final data = doc?.data();
                final status = data?['accountStatus']?.toString();

                if (status == 'deleted') {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _blockAndSignOut('الحساب محذوف');
                  });
                  return const SignInScreen();
                }

                if (status == 'disabled') {
                  if (kDebugMode) {
                    debugPrint('[AuthGate] routing -> ReactivateAccountScreen');
                  }
                  return ReactivateAccountScreen(onReactivated: _refreshStatus);
                }

                if (!statusSnap.hasData) {
                  return const Scaffold(
                    body: Center(child: CircularProgressIndicator()),
                  );
                }

                final completed = data?['onboardingCompleted'] == true;
                final hasProfile =
                    (data?['username'] ?? '').toString().trim().isNotEmpty ||
                        (data?['name'] ?? '').toString().trim().isNotEmpty;
                final needsOnboarding =
                    doc == null || !doc.exists || (!completed && !hasProfile);

                if (needsOnboarding) {
                  final isGoogle =
                  user.providerData.any((p) => p.providerId == 'google.com');
                  final parts = (user.displayName ?? '').trim().split(RegExp(r'\s+'));
                  final first = parts.isNotEmpty ? parts.first : '';
                  final last = parts.length > 1 ? parts.sublist(1).join(' ') : '';
                  return SignUpFlowScreen(
                    skipAccountCreation: isGoogle,
                    initialFirstName: first,
                    initialLastName: last,
                  );
                }

                return _routeAuthenticated(user, isPasswordUser);
              },
            );
          },
        );
      },
    );
  }
}
class SignInScreen extends StatefulWidget {
  const SignInScreen({super.key});
  @override
  State<SignInScreen> createState() => _SignInScreenState();
}

class _SignInScreenState extends State<SignInScreen> {
  final email = TextEditingController();
  final password = TextEditingController();
  final GoogleSignIn _googleSignIn = AuthSessionService.googleSignIn;
  bool loading = false;
  bool googleLoading = false;
  bool _termsAccepted = false;
  bool _obscure = true;

  String _mapAuthError(FirebaseAuthException error) {
    final localizations = S.of(context);
    switch (error.code) {
      case 'invalid-email':
        return localizations.invalidEmailError;
      case 'user-disabled':
        return localizations.userDisabledError;
      case 'user-not-found':
        return localizations.userNotFoundError;
      case 'wrong-password':
        return localizations.wrongPasswordError;
      case 'email-already-in-use':
        return localizations.emailAlreadyInUseError;
      case 'weak-password':
        return localizations.weakPasswordError;
      case 'operation-not-allowed':
        return localizations.emailAuthDisabledError;
      case 'network-request-failed':
        return localizations.networkError;
      case 'too-many-requests':
        return localizations.tooManyRequestsError;
      default:
        return error.message ?? localizations.genericAuthError;
    }
  }

  void _showAuthSnack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context)
        .showSnackBar(SnackBar(content: Text(message)));
  }

  String _mapGoogleAuthError(Object error) {
    if (error is FirebaseAuthException) {
      switch (error.code) {
        case 'network-request-failed':
          return 'تحقق من اتصال الإنترنت ثم أعد المحاولة.';
        case 'invalid-credential':
          return 'بيانات الاعتماد غير صالحة. تحقق من إعدادات تسجيل الدخول.';
        case 'user-disabled':
          return 'تم تعطيل الحساب.';
        default:
          return error.message ??
              'حدث خطأ أثناء تسجيل الدخول عبر Google. حاول مرة أخرى.';
      }
    }
    if (error is PlatformException) {
      final details = [
        error.message,
        error.details?.toString(),
      ].where((value) => value != null && value!.trim().isNotEmpty).join(' ');
      final detailsLower = details.toLowerCase();
      if (error.code == 'sign_in_canceled') {
        return 'تم إلغاء تسجيل الدخول عبر Google.';
      }
      if (error.code == 'network_error') {
        return 'تحقق من اتصال الإنترنت ثم أعد المحاولة.';
      }
      if (error.code == 'api_exception' ||
          detailsLower.contains('apiexception: 10') ||
          detailsLower.contains('apiexception:10') ||
          detailsLower.contains('12500')) {
        return 'تعذر إكمال تسجيل الدخول. تأكد من إعدادات Firebase/Google (SHA-1، الحزمة، OAuth) ثم أعد المحاولة.';
      }
      return 'حدث خطأ أثناء تسجيل الدخول عبر Google. حاول مرة أخرى.';
    }
    return 'حدث خطأ أثناء تسجيل الدخول عبر Google. حاول مرة أخرى.';
  }

  Future<void> _login() async {
    if (!_termsAccepted) {
      return;
    }
    if (loading || googleLoading) {
      if (kDebugMode) {
        debugPrint('[Auth] email login ignored: another auth request is active');
      }
      return;
    }
    final trimmedEmail = email.text.trim();
    final trimmedPassword = password.text.trim();
    if (trimmedEmail.isEmpty || trimmedPassword.isEmpty) {
      _showAuthSnack('الرجاء إدخال البريد الإلكتروني وكلمة المرور.');
      return;
    }
    if (!mounted) return;
    setState(() => loading = true);
    if (kDebugMode) {
      debugPrint('[Auth] email login started: $trimmedEmail');
    }
    try {
      User? user;
      try {
        final credential =
        await FirebaseAuth.instance.signInWithEmailAndPassword(
          email: trimmedEmail,
          password: trimmedPassword,
        );
        user = credential.user;
      } on FirebaseAuthMultiFactorException catch (e) {
        if (!mounted) return;
        final ok = await Navigator.of(context).push<bool>(
          MaterialPageRoute(
            builder: (_) => MfaSignInPage(resolver: e.resolver),
          ),
        );
        if (ok != true) return;
        user = FirebaseAuth.instance.currentUser;
      }

      if (user != null) {
        final isPasswordUser =
        user.providerData.any((info) => info.providerId == 'password');
        if (isPasswordUser && !user.emailVerified) {
          await SessionService.instance.revokeCurrentSession(user.uid);
          await AuthSessionService.signOutFully();
          if (!mounted) return;
          await _showUnverifiedDialog(trimmedEmail, trimmedPassword);
          return;
        }
      }
      if (user != null) {
        if (kDebugMode) {
          debugPrint('[Auth] email login success uid=${user.uid}');
        }
        final profile = await FirebaseFirestore.instance
            .collection('users')
            .doc(user.uid)
            .get();
        final twoFactorEnabled =
            profile.data()?['twoFactorEnabled'] as bool? ?? false;
        if (!twoFactorEnabled) {
          await SessionService.instance.initSession(user.uid, forceNew: true);
        }
      }
    } on FirebaseAuthException catch (e, stackTrace) {
      debugPrint('Login failed: ${e.code} ${e.message}');
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack(_mapAuthError(e));
    } catch (e, stackTrace) {
      debugPrint('Login failed: $e');
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack('حدث خطأ أثناء تسجيل الدخول.');
    } finally {
      if (kDebugMode) {
        debugPrint('[Auth] email login finished loading=false');
      }
      if (mounted) setState(() => loading = false);
    }
  }

  Future<void> _showUnverifiedDialog(
      String email,
      String password,
      ) async {
    final localizations = S.of(context);
    return showDialog<void>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: Text(localizations.verifyEmailTitle),
          content: Text(localizations.verifyEmailToContinue),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: Text(localizations.cancel),
            ),
            TextButton(
              onPressed: () async {
                Navigator.of(dialogContext).pop();
                await _resendVerificationEmail(email, password);
              },
              child: Text(localizations.resendVerificationEmail),
            ),
            // FilledButton(
            //   onPressed: () {
            //     Navigator.of(dialogContext).pop();
            //     Navigator.of(context).push(
            //       MaterialPageRoute(
            //         builder: (_) => VerifyEmailScreen(
            //           email: email,
            //           password: password,
            //         ),
            //       ),
            //     );
            //   },
            //   child: Text(localizations.checkNow),
            // ),
          ],
        );
      },
    );
  }

  Future<void> _resendVerificationEmail(
      String email,
      String password,
      ) async {
    try {
      final credential = await FirebaseAuth.instance
          .signInWithEmailAndPassword(email: email, password: password);
      final user = credential.user;
      if (user == null) {
        _showAuthSnack(S.of(context).genericAuthError);
        return;
      }
      await user.sendEmailVerification();
      await SessionService.instance.revokeCurrentSession(user.uid);
      await AuthSessionService.signOutFully();
      _showAuthSnack(S.of(context).verificationEmailSent);
    } on FirebaseAuthException catch (e) {
      _showAuthSnack(_mapAuthError(e));
    } catch (e, stackTrace) {
      debugPrint('Resend verification failed: $e');
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack(S.of(context).genericAuthError);
    }
  }

  Future<void> _signInWithGoogle() async {
    if (!_termsAccepted) {
      return;
    }
    if (googleLoading || loading) {
      if (kDebugMode) {
        debugPrint('[Auth] google login ignored: another auth request is active');
      }
      return;
    }
    if (!mounted) return;
    setState(() => googleLoading = true);
    if (kDebugMode) {
      debugPrint('[Auth] google login started');
    }
    try {
      // تأكد من إضافة SHA-1/SHA-256 في Firebase لكل من debug/release عند الحاجة.
      if (kDebugMode) {
        debugPrint('[Auth] google login before GoogleSignIn.signIn()');
      }
      final googleUser = await _googleSignIn.signIn();
      if (googleUser == null) {
        debugPrint('Google sign-in canceled by user.');
        _showAuthSnack(
          _mapGoogleAuthError(
            PlatformException(code: 'sign_in_canceled'),
          ),
        );
        return;
      }
      final googleAuth = await googleUser.authentication;
      final credential = GoogleAuthProvider.credential(
        accessToken: googleAuth.accessToken,
        idToken: googleAuth.idToken,
      );
      if (kDebugMode) {
        debugPrint('[Auth] google login credential ready (idToken=${googleAuth.idToken != null})');
      }
      User? user;
      try {
        user = (await FirebaseAuth.instance.signInWithCredential(credential)).user;
      } on FirebaseAuthMultiFactorException catch (e) {
        if (!mounted) return;
        final ok = await Navigator.of(context).push<bool>(MaterialPageRoute(
          builder: (_) => MfaSignInPage(resolver: e.resolver),
        ));
        if (ok != true) return;
        user = FirebaseAuth.instance.currentUser;
      }
      if (kDebugMode) {
        debugPrint('[Auth] google login FirebaseAuth.currentUser=${FirebaseAuth.instance.currentUser?.uid ?? 'null'}');
      }
      if (user != null) {
        await SessionService.instance.initSession(user.uid, forceNew: true);
        if (kDebugMode) {
          debugPrint('[Auth] google login success uid=${user.uid}');
        }
      }
    } on FirebaseAuthException catch (e, stackTrace) {
      debugPrint(
        'Google sign-in failed (FirebaseAuthException): code=${e.code}, message=${e.message}',
      );
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack(_mapGoogleAuthError(e));
    } on PlatformException catch (e, stackTrace) {
      debugPrint(
        'Google sign-in platform error: code=${e.code}, message=${e.message}, details=${e.details}',
      );
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack(_mapGoogleAuthError(e));
    } catch (e, stackTrace) {
      debugPrint('Google sign-in failed: $e');
      debugPrintStack(stackTrace: stackTrace);
      _showAuthSnack('حدث خطأ أثناء تسجيل الدخول عبر Google. حاول مرة أخرى.');
    } finally {
      if (kDebugMode) {
        debugPrint('[Auth] google login finished loading=false');
      }
      if (mounted) setState(() => googleLoading = false);
    }
  }

  Future<void> _register() async {
    if (!mounted) return;
    await Navigator.of(context).push(
      MaterialPageRoute(builder: (_) => const SignUpFlowScreen()),
    );
  }

  String _mapPasswordResetError(FirebaseAuthException error) {
    switch (error.code) {
      case 'invalid-email':
        return S.of(context).invalidEmailError;
      case 'user-not-found':
        return S.of(context).userNotFoundError;
      case 'too-many-requests':
        return S.of(context).tooManyRequestsError;
      default:
        return S.of(context).resetLinkFailed;
