class _SingleScaleAnswer extends StatelessWidget {
  final PollData poll;
  final dynamic value;

  const _SingleScaleAnswer({required this.poll, required this.value});

  List<String> _emojis() {
    const facesA = [
      '😠', '😞', '😕', '😑', '😐', '🙂', '😊', '😄', '😃', '😁',
    ];
    const facesB = ['😭', '😢', '😐', '🙂', '😄'];
    final size = (poll.scaleSize ?? 5).clamp(1, 10);
    final source =
    poll.scaleStyle == LinearScaleStyle.emoji1 ? facesB : facesA;

    return List.generate(size, (i) {
      if (size == 1) return source[source.length ~/ 2];
      final idx = ((i / (size - 1)) * (source.length - 1)).round();
      return source[idx.clamp(0, source.length - 1)];
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final size = (poll.scaleSize ?? 5).clamp(1, 10);
    final n = value is num
        ? value.toInt()
        : int.tryParse(value?.toString() ?? '');

    if (n == null || n < 0 || n >= size) {
      return Text('—', style: TextStyle(color: theme.hintColor));
    }

    final style = poll.scaleStyle;
    final isStars = style == LinearScaleStyle.stars;
    final isEmoji =
        style == LinearScaleStyle.emoji || style == LinearScaleStyle.emoji1;
    final isLine = style == LinearScaleStyle.line;
    final isSlider = style == LinearScaleStyle.slider;

    // ===== نجوم =====
    if (isStars) {
      return Row(
        children: List.generate(
          size,
              (i) => Icon(
            i <= n ? Icons.star_rounded : Icons.star_border_rounded,
            size: 26,
            color: const Color(0xFFFFC107),
          ),
        ),
      );
    }

    // ===== إيموجي =====
    if (isEmoji) {
      final faces = _emojis();
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: List.generate(size, (i) {
          final selected = i == n;
          return AnimatedContainer(
            duration: const Duration(milliseconds: 180),
            width: selected ? 44 : 36,
            height: selected ? 44 : 36,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: selected
                  ? theme.colorScheme.primary.withValues(alpha: 0.14)
                  : Colors.transparent,
              border: selected
                  ? Border.all(
                color: theme.colorScheme.primary,
                width: 2,
              )
                  : null,
            ),
            child: Opacity(
              opacity: selected ? 1 : 0.35,
              child: Text(
                faces[i],
                style: TextStyle(fontSize: selected ? 24 : 18),
              ),
            ),
          );
        }),
      );
    }

    if (isLine) {
      final low =
      poll.scaleMinLabel.trim().isNotEmpty ? poll.scaleMinLabel.trim() : 'Low';
      final high =
      poll.scaleMaxLabel.trim().isNotEmpty ? poll.scaleMaxLabel.trim() : 'High';

      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: List.generate(size, (i) {
              final selected = i == n;
              final filled = i <= n;
              return Expanded(
                child: Container(
                  height: 6,
                  margin: EdgeInsets.only(right: i == size - 1 ? 0 : 4),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(999),
                    color: filled
                        ? theme.colorScheme.primary
                        : theme.dividerColor.withValues(alpha: 0.25),
                  ),
                  child: selected
                      ? Align(
                    alignment: Alignment.centerRight,
                    child: Container(
                      width: 14,
                      height: 14,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: theme.colorScheme.primary,
                        border: Border.all(color: Colors.white, width: 2),
                      ),
                    ),
                  )
                      : null,
                ),
              );
            }),
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Expanded(
                child: Text(
                  low,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: theme.hintColor,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                decoration: BoxDecoration(
                  color: theme.colorScheme.primary.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '${n + 1}',
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w900,
                    color: theme.colorScheme.primary,
                  ),
                ),
              ),
              Expanded(
                child: Text(
                  high,
                  textAlign: TextAlign.end,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: theme.hintColor,
                  ),
                ),
              ),
            ],
          ),
        ],
      );
    }

    // افتراضي
    return Text(
      '${n + 1} / $size',
      style: TextStyle(
        fontSize: 16,
        fontWeight: FontWeight.w800,
        color: theme.colorScheme.primary,
      ),
    );
  }
}

class _SingleSliderAnswer extends StatelessWidget {
  final PollData poll;
  final dynamic value;

  const _SingleSliderAnswer({required this.poll, required this.value});

  double? _parsePercent() {
    if (value == null) return null;

    // قائمة (احتياطي)
    if (value is List && value.isNotEmpty) {
      final first = value.first;
      return _toPercent(first);
    }

    return _toPercent(value);
  }

  double? _toPercent(dynamic v) {
    if (v == null) return null;

    if (v is num) {
      final n = v.toDouble();
      // 0..100
      if (n >= 0 && n <= 100) return n;
      // 0..1
      if (n >= 0 && n <= 1) return n * 100;
    }

    final d = double.tryParse(v.toString());
    if (d == null) return null;
    if (d >= 0 && d <= 100) return d;
    if (d >= 0 && d <= 1) return d * 100;
    return null;
  }

  String _emojiFor(double v) {
    if (v < 20) return '😣';
    if (v < 40) return '😕';
    if (v < 60) return '😐';
    if (v < 80) return '🙂';
    return '😍';
  }

  Color _colorFor(double v) {
    if (v < 25) return Colors.redAccent;
    if (v < 50) return Colors.orangeAccent;
    if (v < 75) return const Color(0xFF26A69A);
    return const Color(0xFF00BFA5);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final percent = _parsePercent();

    if (percent == null) {
      return Text(
        'No answer',
        style: TextStyle(color: theme.hintColor, fontWeight: FontWeight.w600),
      );
    }

    final accent = _colorFor(percent);
    final emoji = _emojiFor(percent);

    return Column(
      children: [
        // رأس: إيموجي + نسبة
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(emoji, style: const TextStyle(fontSize: 28)),
            const SizedBox(width: 10),
            Text(
              '${percent.toStringAsFixed(0)}%',
              style: TextStyle(
                fontSize: 26,
                fontWeight: FontWeight.w900,
                color: accent,
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),

        // شريط السلايدر للعرض فقط — بدون منحنى
        SliderTheme(
          data: SliderTheme.of(context).copyWith(
            trackHeight: 6,
            activeTrackColor: accent,
            inactiveTrackColor: accent.withValues(alpha: 0.18),
            disabledActiveTrackColor: accent,
            disabledInactiveTrackColor: accent.withValues(alpha: 0.18),
            disabledThumbColor: accent,
            thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 8),
            overlayShape: SliderComponentShape.noOverlay,
          ),
          child: Slider(
            value: percent.clamp(0, 100),
            min: 0,
            max: 100,
            onChanged: null,
          ),
        ),
      ],
    );
  }
}







class _DonutPainter extends CustomPainter {
  final List<double> ratios;
  final List<Color> colors;
  final double progress;
  final double strokeWidth;

  _DonutPainter({
    required this.ratios,
    required this.colors,
    required this.progress,
    this.strokeWidth = 22,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final radius = (min(size.width, size.height) - strokeWidth) / 2;
    final rect = Rect.fromCircle(center: center, radius: radius);

    double startAngle = -pi / 2;
    const gap = 0.02; // فاصل بسيط بين القطاعات لإحساس أنظف
    for (var i = 0; i < ratios.length; i++) {
      final sweep = ratios[i] * 2 * pi * progress;
      if (sweep <= 0.001) continue;
      final paint = Paint()
        ..color = colors[i]
        ..style = PaintingStyle.stroke
        ..strokeWidth = strokeWidth
        ..strokeCap = StrokeCap.butt;
      canvas.drawArc(rect, startAngle, max(0.0, sweep - gap), false, paint);
      startAngle += sweep;
    }
  }

  @override
  bool shouldRepaint(covariant _DonutPainter oldDelegate) =>
      oldDelegate.progress != progress || oldDelegate.ratios != ratios;
}

class _PollDonutChart extends StatelessWidget {
  final List<int> counts;
  final List<Color> colors;
  final int total;

  const _PollDonutChart({required this.counts, required this.colors, required this.total});

  @override
  Widget build(BuildContext context) {
    final safeTotal = total == 0 ? 1 : total;
    final ratios = counts.map((c) => c / safeTotal).toList();

    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0, end: 1),
      duration: const Duration(milliseconds: 750),
      curve: Curves.easeOutCubic,
      builder: (context, value, _) {
        return SizedBox(
          width: 148,
          height: 148,
          child: Stack(
            alignment: Alignment.center,
            children: [
              CustomPaint(
                size: const Size(148, 148),
                painter: _DonutPainter(ratios: ratios, colors: colors, progress: value),
              ),
              Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text('$total', style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900)),
                  Text(
                    total == 1 ? 'response' : 'responses',
                    style: TextStyle(fontSize: 11, color: Theme.of(context).hintColor),
                  ),
                ],
              ),
            ],
          ),
        );
      },
    );
  }
}
