    this.authorName,
    this.postTitle,
    this.postBody,
    this.menuButton,
    this.votes,
    this.isLiked,
    this.isDisliked,
    this.commentsCount,
    this.tagsCount,
    this.onLike,
    this.onDislike,
    this.onComment,
    this.onTags,
    this.onOpenFullscreen,
  });

  final String path;
  final String? postId;
  final double maxHeight;
  final String? authorName;
  final String? authorPhotoUrl;
  final String? postTitle;
  final String? postBody;
  final Widget? menuButton;

  final int? votes;
  final bool? isLiked;
  final bool? isDisliked;
