  Future<List<DateTime>?> _pickMultiDays(
      BuildContext context, {
        required List<DateTime> initial,
        required int year,
        required List<int> months,
      }) async {
    final selected = Set<DateTime>.from(
      initial.map((d) => DateTime(d.year, d.month, d.day)),
    );

    return showDialog<List<DateTime>>(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setLocal) {
            return AlertDialog(
              title: const Text('Select days'),
              content: SizedBox(
                width: 320,
                height: 360,
                child: CalendarDatePicker(
                  initialDate: selected.isNotEmpty
                      ? selected.first
                      : DateTime(year, months.isNotEmpty ? months.first : 1, 1),
                  firstDate: DateTime(year, 1, 1),
                  lastDate: DateTime(year, 12, 31),
                  selectableDayPredicate: (day) {
                    if (months.isEmpty) return true;
                    return months.contains(day.month);
                  },
                  onDateChanged: (day) {
                    final key = DateTime(day.year, day.month, day.day);
                    setLocal(() {
                      if (selected.contains(key)) {
                        selected.remove(key);
                      } else {
                        selected.add(key);
                      }
                    });
                  },
                ),
              ),
              // ملاحظة: CalendarDatePicker الافتراضي لا يلوّن عدة أيام.
              // للتمييز البصري استخدم table_calendar أو custom dayBuilder.
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text('Cancel'),
                ),
                TextButton(
                  onPressed: () =>
                      Navigator.pop(ctx, selected.toList()..sort()),
                  child: Text('OK (${selected.length})'),
                ),
              ],
            );
          },
        );
      },
    );
  }
  Future<List<DateTime>?> _pickAllowedDays(
      BuildContext context, {
        required int year,
        required List<int> months,
        required List<DateTime> initial,
      }) async {
    final selected = <DateTime>{
      for (final d in initial) DateTime(d.year, d.month, d.day),
    };

    return showDialog<List<DateTime>>(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setLocal) {
            return AlertDialog(
              title: const Text('الأيام المسموحة'),
              content: SizedBox(
                width: 320,
                height: 400,
                child: Column(
                  children: [
                    Text(
                      'اضغط يوماً لإضافته أو إزالته',
                      style: TextStyle(
                        fontSize: 12,
                        color: Theme.of(ctx).hintColor,
                      ),
                    ),
                    const SizedBox(height: 8),
                    Expanded(
                      child: CalendarDatePicker(
                        initialDate: selected.isNotEmpty
                            ? selected.first
                            : DateTime(
                          year,
                          months.isNotEmpty ? months.first : 1,
                          1,
                        ),
                        firstDate: DateTime(year, 1, 1),
                        lastDate: DateTime(year, 12, 31),
                        selectableDayPredicate: (day) {
                          if (months.isEmpty) return true;
                          return months.contains(day.month);
                        },
                        onDateChanged: (day) {
                          final key =
                          DateTime(day.year, day.month, day.day);
                          setLocal(() {
                            if (selected.contains(key)) {
                              selected.remove(key);
                            } else {
                              selected.add(key);
                            }
                          });
                        },
                      ),
                    ),
                    Text('${selected.length} يوم محدد'),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text('إلغاء'),
                ),
                TextButton(
                  onPressed: () {
                    final list = selected.toList()
                      ..sort((a, b) => a.compareTo(b));
                    Navigator.pop(ctx, list);
                  },
                  child: const Text('تم'),
                ),
              ],
            );
          },
        );
      },
    );
  }
  Future<void> _openDaysPickerDialog(PollQuestion q, PollDateConfig cfg) async {
    var selected = Set<DateTime>.from(
      cfg.allowedDays.map((d) => DateTime(d.year, d.month, d.day)),
    );
    var month = selected.isNotEmpty ? selected.first.month : 1;
    final year = cfg.year;

    await showDialog<void>(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setLocal) {
            final theme = Theme.of(ctx);
            const names = [
              'Jan','Feb','Mar','Apr','May','Jun',
              'Jul','Aug','Sep','Oct','Nov','Dec'
            ];
            final daysInMonth = DateTime(year, month + 1, 0).day;
            final firstWeekday = DateTime(year, month, 1).weekday % 7;

            bool isSel(int day) => selected.any(
                  (d) => d.year == year && d.month == month && d.day == day,
            );

            void toggle(int day) {
              final key = DateTime(year, month, day);
              setLocal(() {
                if (selected.contains(key)) {
                  selected.remove(key);
                } else {
                  selected.add(key);
                }
              });
            }

            return AlertDialog(
              title: const Text('تحديد الأيام'),
              content: SizedBox(
                width: 320,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        IconButton(
                          icon: const Icon(Icons.chevron_left),
                          onPressed: month > 1
                              ? () => setLocal(() => month--)
                              : null,
                        ),
                        Text(
                          '${names[month - 1]} $year',
                          style: const TextStyle(fontWeight: FontWeight.w700),
                        ),
                        IconButton(
                          icon: const Icon(Icons.chevron_right),
                          onPressed: month < 12
                              ? () => setLocal(() => month++)
                              : null,
                        ),
                      ],
                    ),
                    Row(
                      children: ['S','M','T','W','T','F','S']
                          .map((e) => Expanded(
                        child: Center(
                          child: Text(e,
                              style: TextStyle(
                                  fontSize: 11,
                                  color: theme.hintColor)),
                        ),
                      ))
                          .toList(),
                    ),
                    const SizedBox(height: 8),
                    GridView.builder(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      gridDelegate:
                      const SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: 7,
                        mainAxisSpacing: 6,
                        crossAxisSpacing: 6,
                      ),
                      itemCount: firstWeekday + daysInMonth,
                      itemBuilder: (_, index) {
                        if (index < firstWeekday) {
                          return const SizedBox.shrink();
                        }
                        final day = index - firstWeekday + 1;
                        final sel = isSel(day);
                        return GestureDetector(
                          onTap: () => toggle(day),
                          child: AnimatedContainer(
                            duration: const Duration(milliseconds: 150),
                            alignment: Alignment.center,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: sel
                                  ? theme.colorScheme.primary
                                  : Colors.transparent,
                              border: Border.all(
                                color: sel
                                    ? theme.colorScheme.primary
                                    : theme.dividerColor
                                    .withValues(alpha: 0.35),
                              ),
                            ),
                            child: Text(
                              '$day',
                              style: TextStyle(
                                fontWeight:
                                sel ? FontWeight.w800 : FontWeight.w500,
                                color: sel
                                    ? Colors.white
                                    : theme.colorScheme.onSurface,
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                    const SizedBox(height: 8),
                    Text(
                      '${selected.length} يوم محدد',
                      style: TextStyle(fontSize: 12, color: theme.hintColor),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text('إلغاء'),
                ),
                TextButton(
                  onPressed: () {
                    final list = selected.toList()..sort();
                    setState(() {
                      q.dateConfig = PollDateConfig(
                        year: year,
                        months: const [],
                        allowedDays: list,
                        multiSelect: cfg.multiSelect,
                        includeTime: q.includeTime,
                        rangesText: '',
                      );
                    });
                    Navigator.pop(ctx);
                  },
                  child: const Text('تم'),
                ),
              ],
            );
          },
        );
      },
    );
  }

  Widget _buildDaysToggleCalendar({
    required int year,
    required List<DateTime> selected,
    required ValueChanged<List<DateTime>> onChanged,
  }) {
    final theme = Theme.of(context);
    // شهر العرض: من أول يوم محدد أو يناير
    final focusMonth = selected.isNotEmpty
        ? DateTime(selected.first.year, selected.first.month)
        : DateTime(year, 1);

    return _DaysToggleCalendar(
      year: year,
      initialMonth: focusMonth.month,
      selected: selected,
      onChanged: onChanged,
      theme: theme,
    );
  }
  Widget _pollTypeTile(String title, String subtitle, PollQuestionType type, IconData icon, Color color) {
    bool isPressed = false;
    return StatefulBuilder(
      builder: (context, setInnerState) {
        return GestureDetector(
          onTapDown: (_) => setInnerState(() => isPressed = true),
          onTapCancel: () => setInnerState(() => isPressed = false),
          onTap: () {
            setInnerState(() => isPressed = true);
            Future.delayed(const Duration(milliseconds: 35), () {
              Navigator.pop(context);
              final q = PollQuestion(type);
              setState(() {
                _pollQuestions.add(q);
                _order.add(_BuilderItem.poll(q));
              });
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (_scrollController.hasClients) {
                  _scrollController.animateTo(
                    _scrollController.position.maxScrollExtent,
                    duration: const Duration(milliseconds: 350),
                    curve: Curves.easeOut,
                  );
                }
              });
            });
          },
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 100),
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            margin: const EdgeInsets.only(bottom: 8),
            decoration: BoxDecoration(
              color: isPressed
                  ? color.withValues(alpha: 0.12)
                  : Theme.of(context).colorScheme.surface,
              borderRadius: BorderRadius.circular(14),
              border: Border.all(
                color: isPressed
                    ? color
                    : Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.08),
                width: 1.2,
              ),
            ),
            child: Row(
              children: [
                Container(
                  width: 38,
                  height: 38,
                  decoration: BoxDecoration(
                    color: color.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Icon(icon, size: 20, color: color),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        title,
                        style: TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w600,
                          color: Theme.of(context).colorScheme.onSurface,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        subtitle,
                        style: TextStyle(
                          fontSize: 12,
                          color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.55),
                        ),
                      ),
                    ],
                  ),
                ),
                Icon(
                  Icons.chevron_left,
                  size: 20,
                  color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.3),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _fabIcon({
    required IconData icon,
    required String tooltip,
