      appBar: AppBar(
        elevation: 0,
        title: Text(
          'Create a Poll',
          style:TextStyle(fontSize: 17,
          fontWeight: FontWeight.w800,),
        ),

        actions: [
      Container(
        height: 40,
      decoration: BoxDecoration(
      color: _canSave
        ? Colors.blue.shade700          // أزرق غامق لما فيه محتوى
            : Colors.white,                 // أبيض لما فاضي
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: _canSave
              ? Colors.blue.shade700
              : Colors.grey.shade300,
        ),
      ),
      child: TextButton(
              onPressed: (_canSave) ? _savePoll : _showNoPollWarning,
              style: TextButton.styleFrom(
                textStyle: const TextStyle(
                  fontWeight: FontWeight.w800,
                  fontSize: 15,
                ),
              ),
              child: Text('Save',
                style: TextStyle(
                  fontWeight: FontWeight.w800,
                  fontSize: 14,
                  color: _canSave ? Colors.white : Colors.grey,
                ),),
            ),
          ),
        ],
      ),
      floatingActionButton: _showFab
          ? Container(
        padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 6),
        decoration: BoxDecoration(
          color: Theme.of(context).colorScheme.surface.withValues(alpha: 0.8),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color:Theme.of(context).colorScheme.onSurface ),
          boxShadow: [
            BoxShadow(
              color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.25),
              blurRadius: 8,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            _fabIcon(
              icon: Icons.add_circle_outline,
               tooltip: 'Poll',
              onTap: _openPollQuestionPicker,
            ),
            _fabIcon(
              icon: Icons.text_fields,
               tooltip: 'Text',
              onTap: _addTextBlock,
            ),
            _fabIcon(
              icon: Icons.add_photo_alternate_outlined,
               tooltip: 'Picturs',
              onTap: _addImageBlock,
            ),
            _fabIcon(
              icon: Icons.video_collection,
              tooltip: 'Vedios',
                onTap: () async {
                  final newBlock = PostBlock.video();
                  setState(() {
                    _blocks.add(newBlock);
                    _order.add(_BuilderItem.block(newBlock));
                  });

                  final picked = await ImagePicker().pickVideo(source: ImageSource.gallery);
                  if (picked != null) {
                    final file = File(picked.path);
                    final controller = VideoPlayerController.file(file);
                    await controller.initialize();
                    controller.setLooping(true);
                    setState(() {
                      newBlock.video = file;
                      newBlock.videoController = controller;
                    });

