  Widget _datePreviewBox(ThemeData theme, String text) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: theme.dividerColor.withValues(alpha: 0.4)),
        color: theme.colorScheme.surfaceContainerHighest.withValues(alpha: 0.25),
      ),
      child: Row(
        children: [
          Icon(Icons.calendar_today_outlined, size: 18, color: theme.hintColor),
          const SizedBox(width: 10),
          Text(
            text,
            style: TextStyle(
              color: theme.hintColor.withValues(alpha: 0.7),
              fontSize: 14,
            ),
          ),
        ],
      ),
    );
  }

  Widget _includeTimeRow(ThemeData theme, PollQuestion q) {
    return Row(
      children: [
        const Expanded(child: Text('Include time', style: TextStyle(fontSize: 14))),
        Switch(
          value: q.includeTime,
          onChanged: (v) => setState(() => q.includeTime = v),
        ),
      ],
    );
  }

  Widget _buildScalePreview(PollQuestion q, ThemeData theme) {
    final size = q.scaleSize;

    switch (q.scaleStyle) {
      case LinearScaleStyle.numbers:
        return Column(
          children: [
            Row(
              children: List.generate(size, (i) {
                return Expanded(
                  child: Container(
                    margin: const EdgeInsets.symmetric(horizontal: 2),
                    height: 36,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                        color: theme.dividerColor.withValues(alpha: 0.5),
                      ),
                    ),
                    child: Text(
                      '${i + 1}',
                      style: const TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 13,
                      ),
                    ),
                  ),
                );
              }),
            ),
            const SizedBox(height: 6),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(q.scaleMinLabel,
                    style: TextStyle(fontSize: 11, color: theme.hintColor)),
                Text(q.scaleMaxLabel,
                    style: TextStyle(fontSize: 11, color: theme.hintColor)),
              ],
            ),
          ],
        );

      case LinearScaleStyle.stars:
        return Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: List.generate(size, (i) {
            return Icon(Icons.star_outline_rounded,
                size: 28, color: theme.hintColor.withValues(alpha: 0.4));
          }),
        );

      case LinearScaleStyle.emoji:
        const faces = [
          '😠', '😞', '😕', '😑', '😐',
          '🙂', '😊', '😄', '😃', '😁',
        ];
        return Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: List.generate(size, (i) {
            final idx = size <= 1
                ? 0
                : ((i / (size - 1)) * (faces.length - 1)).round();
            return Text(faces[idx], style: const TextStyle(fontSize: 22));
          }),
        );

      case LinearScaleStyle.slider:
      // قيمة تجريبية للمعاينة
        final double value = q.previewSliderValue.clamp(0.0, 100.0);

        String emojiFor(double v) {
          if (v < 20) return '😣';
          if (v < 40) return '😕';
          if (v < 60) return '😐';
          if (v < 80) return '🙂';
          return '😍';
        }

        Color colorFor(double v) {
          if (v < 25) return Colors.redAccent;
          if (v < 50) return Colors.orangeAccent;
          if (v < 75) return const Color(0xFF26A69A);
          return const Color(0xFF00BFA5);
        }

        final accent = colorFor(value);
        final emoji = emojiFor(value);

        return Column(
          children: [
            Text(
              '${value.round()}%',
              style: TextStyle(
                fontSize: 22,
                fontWeight: FontWeight.w900,
                color: accent,
              ),
            ),
            const SizedBox(height: 8),
            SliderTheme(
              data: SliderTheme.of(context).copyWith(
                trackHeight: 6,
                activeTrackColor: accent,
                inactiveTrackColor: accent.withValues(alpha: 0.18),
                overlayColor: accent.withValues(alpha: 0.12),
                thumbShape: _EmojiThumbShape(emoji: emoji, size: 40),
                overlayShape: const RoundSliderOverlayShape(overlayRadius: 28),
              ),
              child: Slider(
                value: q.previewSliderValue,
                min: 0,
                max: 100,
                onChanged: (v) => setState(() => q.previewSliderValue = v),
              ),
            ),
            const SizedBox(height: 4),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  q.scaleMinLabel.isNotEmpty ? q.scaleMinLabel : 'Low',
                  style: TextStyle(fontSize: 12, color: theme.hintColor),
                ),
                Text(
                  q.scaleMaxLabel.isNotEmpty ? q.scaleMaxLabel : 'High',
                  style: TextStyle(fontSize: 12, color: theme.hintColor),
                ),
              ],
            ),
          ],
        );



      case LinearScaleStyle.line:
        return Column(
          children: [
            Slider(
              value: (size / 2).toDouble(),
              min: 1,
              max: size.toDouble(),
              divisions: size - 1,
              onChanged: (_) {},
            ),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(q.scaleMinLabel,
                    style: TextStyle(fontSize: 11, color: theme.hintColor)),
                Text(q.scaleMaxLabel,
                    style: TextStyle(fontSize: 11, color: theme.hintColor)),
              ],
            ),
          ],
        );

      default:
        return const SizedBox.shrink();
    }
  }
}

class _DaysToggleCalendar extends StatefulWidget {
  final int year;
  final int initialMonth;
  final List<DateTime> selected;
  final ValueChanged<List<DateTime>> onChanged;
  final ThemeData theme;

  const _DaysToggleCalendar({
    required this.year,
    required this.initialMonth,
    required this.selected,
    required this.onChanged,
    required this.theme,
  });

  @override
  State<_DaysToggleCalendar> createState() => _DaysToggleCalendarState();
}

class _DaysToggleCalendarState extends State<_DaysToggleCalendar> {
  late int _month;

  @override
  void initState() {
    super.initState();
    _month = widget.initialMonth.clamp(1, 12);
  }

  bool _isSelected(int day) {
    return widget.selected.any((d) =>
    d.year == widget.year && d.month == _month && d.day == day);
  }

  void _toggle(int day) {
    final list = List<DateTime>.from(widget.selected);
    final exists = list.any((d) =>
    d.year == widget.year && d.month == _month && d.day == day);
    if (exists) {
      list.removeWhere((d) =>
      d.year == widget.year && d.month == _month && d.day == day);
    } else {
      list.add(DateTime(widget.year, _month, day));
    }
    list.sort();
    widget.onChanged(list);
  }

  @override
  Widget build(BuildContext context) {
    final theme = widget.theme;
    const names = [
      'Jan','Feb','Mar','Apr','May','Jun',
      'Jul','Aug','Sep','Oct','Nov','Dec'
    ];
    final daysInMonth = DateTime(widget.year, _month + 1, 0).day;
    final firstWeekday = DateTime(widget.year, _month, 1).weekday % 7; // أحد=0

    return Column(
      children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            IconButton(
              icon: const Icon(Icons.chevron_left),
              onPressed: () {
                setState(() {
                  if (_month > 1) {
                    _month--;
                  }
                });
              },
            ),
            Text(
              '${names[_month - 1]} ${widget.year}',
              style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 15),
            ),
            IconButton(
              icon: const Icon(Icons.chevron_right),
              onPressed: () {
                setState(() {
                  if (_month < 12) {
                    _month++;
                  }
                });
              },
            ),
          ],
        ),
        Row(
          children: ['S','M','T','W','T','F','S']
              .map((e) => Expanded(
            child: Center(
              child: Text(e,
                  style: TextStyle(
                      fontSize: 11, color: theme.hintColor)),
            ),
          ))
              .toList(),
        ),
        const SizedBox(height: 6),
        GridView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 7,
            mainAxisSpacing: 4,
            crossAxisSpacing: 4,
          ),
          itemCount: firstWeekday + daysInMonth,
          itemBuilder: (context, index) {
            if (index < firstWeekday) {
              return const SizedBox.shrink();
            }
            final day = index - firstWeekday + 1;
            final sel = _isSelected(day);
            return GestureDetector(
              onTap: () => _toggle(day),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 150),
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: sel
                      ? theme.colorScheme.primary
                      : Colors.transparent,
                  border: Border.all(
                    color: sel
                        ? theme.colorScheme.primary
                        : theme.dividerColor.withValues(alpha: 0.35),
                  ),
                ),
                child: Text(
                  '$day',
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: sel ? FontWeight.w800 : FontWeight.w500,
                    color: sel
                        ? Colors.white
                        : theme.colorScheme.onSurface,
                  ),
                ),
              ),
            );
          },
        ),
      ],
    );
  }
}

enum DateRestrictMode { months, days, ranges }

class _BuilderItem {
  final PostBlock? block;
  final PollQuestion? poll;

  _BuilderItem.block(this.block) : poll = null;
  _BuilderItem.poll(this.poll) : block = null;

  bool get isBlock => block != null;
}

//=======================================================
class PollDateConfig {
  final int year;
  final List<int> months;           // الوضع القديم
  final List<DateTime> allowedDays; // أيام محددة (يوم/شهر/سنة)
  final bool includeTime;
  final bool multiSelect;// أكثر من يوم
  final String? rangesText;
  final DateTime? rangeStart;
  final DateTime? rangeEnd;


  PollDateConfig({
    required this.year,
    this.months = const [],
    this.allowedDays = const [],
    this.includeTime = false,
    this.multiSelect = false,
    this.rangeStart,
    this.rangesText,
    this.rangeEnd,
  });

  bool get hasSpecificDays => allowedDays.isNotEmpty;
  bool get hasRange => rangeStart != null && rangeEnd != null;
}

class PollData {
  final String question;
  final PollQuestionType type;
  final List<String> options;
  final List<String> gridRows;
  final List<String> gridColumns;
  final LinearScaleStyle? scaleStyle;
  final int? scaleSize;
  final PollDateConfig? dateConfig;
  final TimeOfDay? selectedTime;
  final bool isRequired;
  final String scaleMinLabel;
  final String scaleMaxLabel;
  final bool includeTime;
  final bool multiSelect; // ← أضف هذا

  PollData({
    required this.question,
    required this.type,
    this.options = const [],
    this.gridRows = const [],
    this.gridColumns = const [],
    this.scaleStyle,
    this.scaleSize,
    this.dateConfig,
    this.selectedTime,
    this.isRequired = false,
    this.scaleMinLabel = 'Low',
    this.scaleMaxLabel = 'High',
    this.includeTime = false,
    this.multiSelect = false,
  });

  factory PollData.fromQuestion(PollQuestion q) {
    return PollData(
      question: q.questionCtrl.text.trim(),
      type: q.type,
      options: q.options
          .map((c) => c.text.trim())
          .where((o) => o.isNotEmpty)
          .toList(),
      gridRows: List.from(q.gridRows),
      gridColumns: List.from(q.gridColumns),
      scaleStyle: q.scaleStyle,
      scaleSize: q.scaleSize,
      dateConfig: q.dateConfig,
      includeTime: q.includeTime,
      multiSelect: q.dateConfig?.multiSelect ?? q.multiSelectDate,
      selectedTime: q.selectedTime,
      isRequired: q.confirmed,
      scaleMinLabel: q.scaleMinLabel.isEmpty ? 'Low' : q.scaleMinLabel,
      scaleMaxLabel: q.scaleMaxLabel.isEmpty ? 'High' : q.scaleMaxLabel,
    );
  }
}

class DatePollWidget extends StatefulWidget {
  final PollDateConfig? initialConfig;
  final void Function(PollDateConfig config) onConfirm;

  const DatePollWidget({
    super.key,
    this.initialConfig,
    required this.onConfirm,
  });

  @override
  State<DatePollWidget> createState() => _DatePollWidgetState();
}

class _DatePollWidgetState extends State<DatePollWidget> {
  late TextEditingController _yearController;
  final Set<int> _selectedMonths = {};
  bool _confirmed = false;
  late PageController _pageController;
  int _currentPage = 0;
  static const int maxSelectableDays = 31;

// year -> month -> days
  final Map<int, Map<int, Set<int>>> _selectedDays = {};

  Set<int> _daysFor(int year, int month) {
    _selectedDays.putIfAbsent(year, () => {});
    _selectedDays[year]!.putIfAbsent(month, () => {});
    return _selectedDays[year]![month]!;
  }

  bool _isDaySelected(int year, int month, int day) {
    return _daysFor(year, month).contains(day);
  }

  void _toggleDay(int year, int month, int day) {
    final days = _daysFor(year, month);

    setState(() {
      if (days.contains(day)) {
        days.remove(day);
      } else {
        if (days.length >= maxSelectableDays) return;
        days.add(day);
      }
    });
  }

  static const months = [
    'يناير',
    'فبراير',
    'مارس',
    'أبريل',
    'مايو',
    'يونيو',
    'يوليو',
    'أغسطس',
    'سبتمبر',
    'أكتوبر',
    'نوفمبر',
    'ديسمبر',
  ];

  @override
  void dispose() {
    _pageController.dispose();
    _yearController.dispose();
    super.dispose();
  }

  @override
  void initState() {
    super.initState();

    _yearController = TextEditingController(
      text: widget.initialConfig?.year.toString(),
    );

    if (widget.initialConfig != null) {
      _selectedMonths.addAll(widget.initialConfig!.months);
      _confirmed = true;
    }

    _pageController = PageController();
  }

  Widget _buildCalendars() {
    final year = int.parse(_yearController.text);
    final monthsList = _selectedMonths.toList()..sort();

    return Column(
      children: [
        SizedBox(
          height: 280,
          child: PageView.builder(
            controller: _pageController,
            itemCount: monthsList.length,
            onPageChanged: (i) {
              setState(() => _currentPage = i);
            },
            itemBuilder: (context, index) {
              final month = monthsList[index];

              return Padding(
                padding: const EdgeInsets.symmetric(horizontal: 0),
                child: Card(
                  elevation: 3,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Padding(
                    padding: const EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const SizedBox(height: 8),
                        Expanded(
                          child: CalendarDatePicker(
                            initialDate: DateTime(year, month, 1),
                            firstDate: DateTime(year, month, 1),
                            lastDate: DateTime(year, month + 1, 0),
                            onDateChanged: (date) {
                              _toggleDay(year, month, date.day);
                            },
                            selectableDayPredicate: (date) {
                              final days = _daysFor(year, month);
                              return days.contains(date.day) ||
                                  days.length < maxSelectableDays;
                            },
                          ),
                        ),
                        const SizedBox(height: 0),
                        // بدل الـ Wrap
                        if (_daysFor(year, month).isNotEmpty)
                          SizedBox(
                            height: 40, // ارتفاع الشريط
                            child: ListView(
                              scrollDirection: Axis.horizontal,
                              children: _daysFor(year, month)
                                  .map(
                                    (d) => Padding(
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 4),
                                  child: Chip(
                                    label: Text('$d'),
                                    onDeleted: () =>
                                        _toggleDay(year, month, d),
                                  ),
                                ),
                              )
                                  .toList(),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              );
            },
          ),
        ),

        const SizedBox(height: 12),

        // 👇 المؤشر السفلي (العلامة المائية)
        _buildPageIndicator(monthsList.length),
      ],
    );
  }

  Widget _buildPageIndicator(int count) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: List.generate(count, (index) {
        final isActive = index == _currentPage;

        return AnimatedContainer(
          duration: const Duration(milliseconds: 300),
          margin: const EdgeInsets.symmetric(horizontal: 4),
          width: isActive ? 16 : 8,
          height: 8,
          decoration: BoxDecoration(
            color: isActive
                ? Theme.of(context).colorScheme.primary
                : Colors.grey.shade400,
            borderRadius: BorderRadius.circular(4),
          ),
        );
      }),
    );
  }

  // ⬇⬇⬇ الكود الذي سألت عنه يوضع هنا ⬇⬇⬇
  @override
  Widget build(BuildContext context) {
    if (_confirmed) return _buildCalendars();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        TextField(
          controller: _yearController,
          keyboardType: TextInputType.number,
          decoration: const InputDecoration(labelText: 'السنة'),
        ),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          children: List.generate(12, (i) {
            final m = i + 1;
            return ChoiceChip(
              label: Text(months[i]),
              selected: _selectedMonths.contains(m),
              onSelected: (v) {
                setState(() {
                  v ? _selectedMonths.add(m) : _selectedMonths.remove(m);
                });
              },
            );
          }),
        ),
        const SizedBox(height: 12),
        TextButton(
          onPressed: _yearController.text.isEmpty || _selectedMonths.isEmpty
              ? null
              : () {
            setState(() => _confirmed = true);
            widget.onConfirm(
              PollDateConfig(
                year: int.parse(_yearController.text),
                months: _selectedMonths.toList(),
              ),
            );
          },
          child: const Text('تأكيد'),
        ),
      ],
    );
  }
}

class _DateModeChip extends StatelessWidget {
  final String label;
  final IconData icon;
  final bool selected;
  final VoidCallback onTap;

  const _DateModeChip({
    required this.label,
    required this.icon,
    required this.selected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
        decoration: BoxDecoration(
          color: selected
              ? theme.colorScheme.primary.withValues(alpha: 0.12)
              : theme.colorScheme.surfaceContainerHighest.withValues(alpha: 0.4),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: selected
                ? theme.colorScheme.primary
                : theme.dividerColor.withValues(alpha: 0.3),
            width: selected ? 1.5 : 1,
          ),
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(
              icon,
              size: 18,
              color: selected ? theme.colorScheme.primary : theme.hintColor,
            ),
            const SizedBox(width: 6),
            Flexible(
              child: Text(
                label,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
                  color: selected ? theme.colorScheme.primary : theme.colorScheme.onSurface,
                ),
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

//================GoogleFormQuestionCard========================
class GoogleFormQuestionCard extends StatelessWidget {
  final String typeLabel;
  final IconData typeIcon;
  final Widget? questionField;
  final Widget? body; // الخيارات أو المحتوى الخاص
  final bool isRequired;
  final ValueChanged<bool>? onRequiredChanged;
  final VoidCallback? onDuplicate;
  final VoidCallback? onDelete;
  final VoidCallback? onMore;
  final VoidCallback? onMoveUp;
  final VoidCallback? onMoveDown;
  final bool canMoveUp;
  final bool canMoveDown;

  const GoogleFormQuestionCard({
    super.key,
    required this.typeLabel,
    required this.typeIcon,
    required this.questionField,
    this.body,
    this.isRequired = false,
    this.onRequiredChanged,
    this.onDuplicate,
    this.onDelete,
    this.onMore,
    this.onMoveUp,
    this.onMoveDown,
    this.canMoveUp = false,
    this.canMoveDown = false,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      decoration: BoxDecoration(
        color: isDark ? theme.colorScheme.surfaceContainerHighest : Colors.white,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: isDark ? Colors.grey.shade700 : Colors.grey.shade300,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.04),
            blurRadius: 6,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // ===== رأس النوع =====
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
            decoration: BoxDecoration(
              color: isDark
                  ? Colors.grey.shade800
                  : const Color(0xFFF1F3F4),
              borderRadius: const BorderRadius.vertical(top: Radius.circular(12)),
            ),
            child: Row(
              children: [
                Icon(typeIcon, size: 18, color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    typeLabel,
                    style: TextStyle(
                      fontWeight: FontWeight.w600,
                      fontSize: 14,
                      color: theme.colorScheme.onSurface,
                    ),
                  ),
                ),
                // أزرار الترتيب
                if (onMoveUp != null)
                  IconButton(
                    icon: const Icon(Icons.keyboard_arrow_up, size: 20),
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(),
                    onPressed: canMoveUp ? onMoveUp : null,
                  ),
                if (onMoveDown != null)
                  IconButton(
                    icon: const Icon(Icons.keyboard_arrow_down, size: 20),
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(),
                    onPressed: canMoveDown ? onMoveDown : null,
                  ),
              ],
            )
          ),

          // ===== المحتوى =====
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 14, 14, 8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (questionField != null) questionField!,
                if (body != null) ...[
                  if (questionField != null) const SizedBox(height: 12),
                  body!,
                ],
              ],
            ),
          ),

          // ===== الشريط السفلي =====
          const Divider(height: 1),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
            child: Row(
              children: [
                // Required
                if (onRequiredChanged != null) ...[
                  Text(
                    'Required',
                    style: TextStyle(
                      fontSize: 13,
                      color: theme.hintColor,
                    ),
                  ),
                  const SizedBox(width: 6),
                  Switch(
                    value: isRequired,
                    onChanged: onRequiredChanged,
                    materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  ),
                ],
                const Spacer(),
                if (onDuplicate != null)
                  IconButton(
                    icon: const Icon(Icons.copy_outlined, size: 20),
                    tooltip: 'Duplicate',
                    onPressed: onDuplicate,
                  ),
                if (onDelete != null)
                  IconButton(
                    icon: const Icon(Icons.delete_outline, size: 20),
                    tooltip: 'Delete',
                    onPressed: onDelete,
                  ),
                if (onMore != null)
                  IconButton(
                    icon: const Icon(Icons.more_vert, size: 20),
                    onPressed: onMore,
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

//=======================================================
enum PollQuestionType {
  shortText,
  longText,
  checkbox,
  linearScale,
  dropdown,
  singelOptin,
  grid,
  checkboxGrid,
  date,
  time,
}

class PollQuestion {
  PollQuestionType type;
  double previewSliderValue = 50;
  bool includeTime = false;
  bool multiSelectDate = false;
  TextEditingController? rangesCtrl;
  DateRestrictMode dateMode = DateRestrictMode.months;
  final scaleMinCtrl = TextEditingController(text: 'Low');
  final scaleMaxCtrl = TextEditingController(text: 'High');

  String get scaleMinLabel => scaleMinCtrl.text.trim();
  String get scaleMaxLabel => scaleMaxCtrl.text.trim();

// أضفه داخل class PollQuestion
  factory PollQuestion.fromPollData(PollData data) {
    final q = PollQuestion(data.type);
    q.questionCtrl.text = data.question;
    q.includeTime = data.includeTime;
    q.confirmed = data.isRequired;
    q.multiSelectDate = data.multiSelect;
    if (data.dateConfig != null) {
      q.dateConfig = data.dateConfig;
    }
    // options
    if (data.dateConfig != null) {
      q.dateConfig = data.dateConfig;
      final t = data.dateConfig!.rangesText?.trim() ?? '';
      if (t.isNotEmpty) {
        q.dateMode = DateRestrictMode.ranges;
      } else if (data.dateConfig!.allowedDays.isNotEmpty) {
        q.dateMode = DateRestrictMode.days;
      } else {
        q.dateMode = DateRestrictMode.months;
      }
    }
    q.multiSelectDate = data.multiSelect;


    // grid
    if (data.gridRows.isNotEmpty) {
      q.gridRows = List.from(data.gridRows);
      q.gridColumns = List.from(data.gridColumns);
      q.gridConfirmed = true;
      q.initGrid();
    }

    // linearScale
    if (data.scaleStyle != null) {
      q.scaleStyle = data.scaleStyle!;
      q.scaleSize = data.scaleSize ?? 5;
      q.scaleConfirmed = true;
    }

    // date
    if (data.dateConfig != null) {
      q.dateConfig = data.dateConfig;
    }

    // time
    if (data.selectedTime != null) {
      q.selectedTime = data.selectedTime;
      q.timeController ??= TextEditingController();
    }
    q.scaleMinCtrl.text = data.scaleMinLabel;
    q.scaleMaxCtrl.text = data.scaleMaxLabel;
    q.scaleSize = data.scaleSize ?? 5;
    q.scaleStyle = data.scaleStyle ?? LinearScaleStyle.numbers;

    return q;
  }
  // ===== عام =====
  TextEditingController questionCtrl = TextEditingController();
  bool confirmed = false;
  Key rebuildKey = UniqueKey();

  // ===== Options (checkbox / radio / dropdown) =====
  List<TextEditingController> options = [];
  List<bool> selectedOptions = []; // checkbox + multiple
  int? selectedOptionIndex;        // radio + dropdown

  // ===== Grid / CheckboxGrid =====
  List<String> gridRows = [];
  List<String> gridColumns = [];
  List<List<bool>> gridSelections = [];
  bool gridConfirmed = false;

  // ===== Date =====
  PollDateConfig? dateConfig;

  // ===== Linear Scale =====
  LinearScaleStyle scaleStyle;
  int scaleSize;
  bool scaleConfirmed;

  int? selectedNumber;
  int lineValue;
  int? selectedEmoji;
  int? selectedEmoji1;

  // ===== Time =====
  TextEditingController? timeController;
  TimeOfDay? selectedTime;

  // ================= CONSTRUCTOR =================

  PollQuestion(this.type)
      : scaleStyle = LinearScaleStyle.numbers,
        scaleSize = 5,
        scaleConfirmed = false,
        lineValue = 1 {
    if (_needsOptions(type)) {
      options = [
        TextEditingController(),
        TextEditingController(),
      ];

      selectedOptions = List.filled(options.length, false);
    }

    if (type == PollQuestionType.time) {
      timeController = TextEditingController();
    }
  }

  // ================= GRID INIT =================

  void initGrid() {
    if (gridRows.isNotEmpty && gridColumns.isNotEmpty) {
      gridSelections = List.generate(
        gridRows.length,
            (_) => List.filled(gridColumns.length, false),
      );
    }
  }

  // ================= RESET (UNDO) =================

  void reset() {
    confirmed = false;
    rebuildKey = UniqueKey();

    switch (type) {
      case PollQuestionType.linearScale:
        scaleConfirmed = false;
        selectedNumber = null;
        selectedEmoji = null;
        selectedEmoji1 = null;
        lineValue = 1;
        break;

      case PollQuestionType.grid:
      case PollQuestionType.checkboxGrid:
        gridConfirmed = false;
        initGrid();
        break;

      case PollQuestionType.checkbox:
      case PollQuestionType.singelOptin:
        selectedOptions = List.filled(options.length, false);
        break;

      case PollQuestionType.dropdown:
        selectedOptionIndex = null;
        break;

      case PollQuestionType.time:
        selectedTime = null;
        timeController?.clear();
        break;

      case PollQuestionType.date:
        dateConfig = null;
        break;

      default:
        break;
    }
  }

  // ================= HELPERS =================

  static bool _needsOptions(PollQuestionType type) {
    return const [
      PollQuestionType.checkbox,
      PollQuestionType.dropdown,
      PollQuestionType.singelOptin,
      PollQuestionType.grid,
      PollQuestionType.checkboxGrid,
    ].contains(type);
  }
}

enum BlockType { text, image, video }

class PostBlock {
  final BlockType type;
  final TextEditingController? textController;
  File? image;
  File? video;
  final FocusNode? focusNode;
  VideoPlayerController? videoController;

  PostBlock.text()
      : type = BlockType.text,
        textController = TextEditingController(),
        focusNode = FocusNode(),
        image = null;

  PostBlock.image()
      : type = BlockType.image,
        textController = TextEditingController(),
        focusNode = FocusNode(),
        image = null;

  PostBlock.video()
      : type = BlockType.video,
        textController = TextEditingController(),
        focusNode = FocusNode(),
        image = null,
        video = null,
        videoController = null;
}


