  Future<void> _submitComment() async {
    final postId = widget.post.id;
    if (postId == null || postId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تحديد المنشور')),
      );
      return;
    }

    if (_editingComment != null) {
      await _saveEditedComment(_editingComment!);
      return;
    }

    final replyTo = _replyTo;
    final attachment = _attachment; // NEW
    if (!_canComment) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('التعليق غير مسموح على هذا المنشور')),
      );
      return;
    }
    await _postComment(
      context: context,
      postId: postId,
      text: _commentController.text,
      replyTo: replyTo,
      attachment: attachment,
      onSuccess: (newComment, isReply) {
        if (!mounted) return;
        setState(() {
          if (isReply) {
            _findCommentLocal(widget.post.comments, replyTo!.id, (c) {
              c.replies.insert(0, newComment);
            });
          } else {
            widget.post.comments.insert(0, newComment);
          }
          _replyTo = null;
          _attachment = null; // NEW
          _commentController.clear();
        });
        FocusScope.of(context).unfocus();
      },
    );
  }
}
