  List<_ProfileMediaItem> _mediaFromPosts(List<_Post> posts) {
    final items = <_ProfileMediaItem>[];
    for (final p in posts) {
      for (final path in p.imagePaths) {
        if (path.trim().isNotEmpty) {
          items.add(_ProfileMediaItem(
            post: p,
            path: path.trim(),
            isVideo: false,
          ));
        }
      }
      for (final path in p.videoPaths) {
        if (path.trim().isNotEmpty) {
          items.add(_ProfileMediaItem(
            post: p,
            path: path.trim(),
            isVideo: true,
          ));
        }
      }
    }
    return items;
  }
  Widget _metaIconButton(
      _ProfileTheme t, {
        required IconData icon,
        required String tooltip,
        required VoidCallback onTap,
      }) {
    return Tooltip(
      message: tooltip,
      child: Material(
        color: t.isDark
            ? Colors.white.withValues(alpha: 0.08)
            : Colors.black.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(10),
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(10),
          child: SizedBox(
            width: 36,
            height: 36,
            child: Icon(icon, size: 18, color: AppTeal.main),
          ),
        ),
      ),
    );
  }
  Future<void> _openLink(String url) async {
    var u = url.trim();
    if (u.isEmpty) return;
    if (!u.startsWith('http')) u = 'https://$u';
    final uri = Uri.tryParse(u);
    if (uri == null) return;
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }
  // NEW: واجهة معلومات الحساب — بدّلت بيها الـ Drawer الجانبي
  void _showAccountInfoSheet() {
    final user = FirebaseAuth.instance.currentUser;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _AccountInfoPanel(
        firstName: firstName,
        lastName: lastName,
        birthDate: birthDate,
        residence: residence,
        uni: uni,
        fac: fac,
        major: section,
        work: work,
        phone: phone,
        email: user?.email ?? email,
        gender: gender,
        otherInfo: otherInfo,
        studyLevel: studyLevel,
        github: github,
        linkedin: linkedin,
        portfolio: portfolio,
        onSaved: (v) {
          setState(() {
            firstName = v.firstName;
            lastName = v.lastName;
            birthDate = v.birthDate;
            residence = v.residence;
            uni = v.uni;
            fac = v.fac;
            section = v.major;
            work = v.work;
            phone = v.phone;
            gender = v.gender;
            otherInfo = v.otherInfo;
            studyLevel = v.studyLevel;
            github = v.github;
            linkedin = v.linkedin;
            portfolio = v.portfolio;
            if (v.firstName.isNotEmpty || v.lastName.isNotEmpty) {
              userName = [v.firstName, v.lastName]
                  .where((e) => e.trim().isNotEmpty)
                  .join(' ');
            }
          });
          final uid = FirebaseAuth.instance.currentUser?.uid;
          if (uid != null && userName.trim().isNotEmpty) {
            AuthorProfiles.putName(uid, userName.trim());
            propagateAuthorToPosts(uid: uid, authorName: userName.trim(), useFullName: true);
          }
        }
      ),
    );
  }
