  Widget _buildGroupCard(
      BuildContext context, {
        required List<Widget> children,
      }) {
    final theme = Theme.of(context);
    final colors = theme.colorScheme;

    return Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: colors.surfaceContainerHighest.withOpacity(.42),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: colors.outlineVariant.withOpacity(.28),
        ),
      ),
      child: Column(
        children: _addDividers(
          children,
          dividerColor: colors.outlineVariant.withOpacity(.28),
        ),
      ),
    );
  }

  List<Widget> _addDividers(
      List<Widget> children, {
        required Color dividerColor,
      }) {
    final result = <Widget>[];

    for (var i = 0; i < children.length; i++) {
      result.add(children[i]);

      if (i < children.length - 1) {
        result.add(
          Divider(
            height: 1,
            thickness: 1,
            indent: 72,
            endIndent: 16,
            color: dividerColor,
          ),
        );
      }
    }

    return result;
  }

  Widget _settingsTile(
      BuildContext context, {
        required IconData icon,
        required String title,
        required String subtitle,
        required VoidCallback onTap,
        Color? iconColor,
        Color? titleColor,
        bool showArrow = true,
      }) {
    final theme = Theme.of(context);
    final colors = theme.colorScheme;

    final resolvedIconColor = iconColor ?? colors.primary;

    return ListTile(
      onTap: onTap,
      contentPadding: const EdgeInsets.symmetric(
        horizontal: 14,
        vertical: 7,
      ),
      minVerticalPadding: 8,
      leading: Container(
