class _BlockedAccount {
  const _BlockedAccount({
    required this.id,
    required this.name,
    this.photoUrl,
  });
  final String id;
  final String name;
  final String? photoUrl;
}

class _BlockedAccountsSheet extends StatefulWidget {
  const _BlockedAccountsSheet();

  @override
  State<_BlockedAccountsSheet> createState() => _BlockedAccountsSheetState();
}

class _BlockedAccountsSheetState extends State<_BlockedAccountsSheet> {
  bool _loading = true;
  String? _error;
  List<_BlockedAccount> _items = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) {
      setState(() {
        _loading = false;
        _error = 'يجب تسجيل الدخول أولاً';
        _items = [];
      });
      return;
    }

    setState(() {
      _loading = true;
      _error = null;
    });

    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('blocked_accounts')
          .get();

      final items = snap.docs.map((d) {
        final data = d.data();
        final name = (data['targetName'] ?? 'حساب محظور').toString().trim();
        return _BlockedAccount(
          id: d.id,
          name: name.isEmpty ? 'حساب محظور' : name,
          photoUrl: data['targetPhotoUrl']?.toString(),
        );
      }).toList()
        ..sort((a, b) => a.name.compareTo(b.name));

      if (!mounted) return;
      setState(() {
        _items = items;
        _loading = false;
      });
    } catch (e) {
      debugPrint('load blocked accounts failed: $e');
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = 'تعذر تحميل الحسابات المحظورة';
      });
    }
  }

  Future<void> _unblock(_BlockedAccount account) async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
          title: const Text('إلغاء الحظر؟'),
          content: Text('ستظهر منشورات ${account.name} في الفيد مجددًا.'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('إلغاء الحظر'),
            ),
          ],
        ),
      ),
    );
    if (confirmed != true) return;

    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('blocked_accounts')
          .doc(account.id)
          .delete();
      if (!mounted) return;
      setState(() => _items.removeWhere((e) => e.id == account.id));
      blockedListRevision.value++;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(content: Text('تم إلغاء حظر ${account.name}')),
      );
    } catch (e) {
      debugPrint('unblock failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        const SnackBar(content: Text('تعذر إلغاء الحظر')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final h = MediaQuery.sizeOf(context).height * 0.72;

    return Directionality(
      textDirection: TextDirection.rtl,
      child: SafeArea(
        child: SizedBox(
          height: h,
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
                child: Text(
                  'الحسابات المحظورة',
                  style: theme.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Expanded(
                child: _loading
                    ? const Center(child: CircularProgressIndicator())
                    : _error != null
                    ? Center(child: Text(_error!))
                    : _items.isEmpty
                    ? const EmptyState(
                  icon: Icons.block_rounded,
                  title: 'لا توجد حسابات محظورة',
                )
                    : ListView.separated(
                  padding: const EdgeInsets.fromLTRB(8, 0, 8, 16),
                  itemCount: _items.length,
                  separatorBuilder: (_, __) =>
                  const Divider(height: 1),
                  itemBuilder: (context, i) {
                    final a = _items[i];
                    final photo = a.photoUrl?.trim() ?? '';
                    return ListTile(
                      leading: CircleAvatar(
                        radius: 22,
                        backgroundColor: theme.colorScheme.primary
                            .withValues(alpha: 0.12),
                        backgroundImage: photo.startsWith('http')
                            ? NetworkImage(photo)
                            : null,
                        child: photo.startsWith('http')
                            ? null
                            : Icon(
                          Icons.person_rounded,
                          color: theme.colorScheme.primary,
                        ),
                      ),
                      title: Text(
                        a.name,
                        style: const TextStyle(
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      trailing: TextButton(
                        onPressed: () => _unblock(a),
                        child: const Text('إلغاء الحظر'),
                      ),
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
class AuthorProfiles {
  AuthorProfiles._();

  static final ValueNotifier<int> revision = ValueNotifier(0);
  static final Map<String, String?> _photos = {};
  static final Set<String> _loading = {};

  static final Map<String, String?> _names = {};

  static String? nameOf(String? uid) {
    if (uid == null || uid.isEmpty) return null;
    return _names[uid];
  }

  static void putName(String uid, String name) {
    _names[uid] = name;
    revision.value++;
  }

  static String? photoOf(String? uid) {
    if (uid == null || uid.isEmpty) return null;
    return _photos[uid];
  }

  static void put(String uid, String? photoUrl) {
    _photos[uid] = photoUrl;
    revision.value++;
  }

  static Future<void> ensure(String uid) async {
    if (uid.isEmpty || _loading.contains(uid)) return;
    if (_photos.containsKey(uid) && _names.containsKey(uid)) return;
    _loading.add(uid);
    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .get();
      final data = doc.data() ?? <String, dynamic>{};
      _photos[uid] = data['profileImageUrl']?.toString();
      final fn = (data['firstName'] ?? '').toString().trim();
      final ln = (data['lastName'] ?? '').toString().trim();
      final display = (data['displayName'] ?? '').toString().trim();
      final fromNames = [fn, ln].where((e) => e.isNotEmpty).join(' ');
      _names[uid] = fromNames.isNotEmpty
          ? fromNames
          : (display.isNotEmpty ? display : _names[uid]);
      revision.value++;
    } catch (e) {
      debugPrint('AuthorProfiles.ensure failed: $e');
    } finally {
      _loading.remove(uid);
    }
  }
}

class LiveAuthorPhoto extends StatefulWidget {
  const LiveAuthorPhoto({
    super.key,
    required this.userId,
    this.fallbackUrl,
    this.size = 40,
    this.radius,
    this.iconSize = 22,
  });

  final String? userId;
  final String? fallbackUrl;
  final double size;
  final double? radius;
  final double iconSize;

  @override
  State<LiveAuthorPhoto> createState() => _LiveAuthorPhotoState();
}

class _LiveAuthorPhotoState extends State<LiveAuthorPhoto> {
  void _load() {
    final id = widget.userId?.trim() ?? '';
    if (id.isNotEmpty) AuthorProfiles.ensure(id);
  }

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void didUpdateWidget(covariant LiveAuthorPhoto oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.userId != widget.userId) _load();
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<int>(
      valueListenable: AuthorProfiles.revision,
      builder: (context, _, __) {
        final live = AuthorProfiles.photoOf(widget.userId)?.trim() ?? '';
        final fallback = widget.fallbackUrl?.trim() ?? '';
        final url = live.startsWith('http')
            ? live
            : fallback.startsWith('http')
            ? fallback
            : '';
        final r = widget.radius ?? widget.size / 2;
        return Container(
          width: widget.size,
          height: widget.size,
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(r),
            color: Theme.of(context).colorScheme.primary.withValues(alpha: 0.10),
          ),
          child: url.isNotEmpty
              ? CachedNetworkImage(
            imageUrl: url,
            fit: BoxFit.cover,
            memCacheWidth: 160,
            errorWidget: (_, __, ___) => Icon(
              Icons.person_rounded,
              size: widget.iconSize,
              color: Theme.of(context)
                  .colorScheme
                  .primary
                  .withValues(alpha: 0.75),
            ),
            placeholder: (_, __) => const SizedBox.shrink(),
          )
              : Icon(
            Icons.person_rounded,
            size: widget.iconSize,
            color: Theme.of(context)
                .colorScheme
                .primary
                .withValues(alpha: 0.75),
          ),
        );
      },
    );
  }
}

