class _ProfileCommentsPane extends StatelessWidget {
  const _ProfileCommentsPane({
    required this.loading,
    this.error,
    this.onRetry,
    required this.comments,
    required this.t,
  });

  final bool loading;
  final String? error;
  final VoidCallback? onRetry;
  final List<_ProfileCommentHit> comments;
  final _ProfileTheme t;

  @override
  Widget build(BuildContext context) {
    if (loading) {
      return const Center(
        child: SizedBox(
          width: 28,
          height: 28,
          child: CircularProgressIndicator(strokeWidth: 2.5),
        ),
      );
    }
    if (error != null) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
      Text(error!), TextButton(onPressed: onRetry, child: const Text('إعادة المحاولة')),
    ]));
    if (comments.isEmpty) {
      return CustomScrollView(
        slivers: [
          SliverFillRemaining(
            hasScrollBody: false,
            child: Center(
              child: Text('لا توجد تعليقات',
                  style: TextStyle(color: t.textFaint)),
            ),
          ),
        ],
      );
    }
    return CustomScrollView(
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.fromLTRB(12, 8, 12, 100),
          sliver: SliverList(
            delegate: SliverChildBuilderDelegate(
                  (context, i) =>
                  _ProfileCommentTile(hit: comments[i], t: t),
              childCount: comments.length,
            ),
          ),
        ),
      ],
    );
  }
}
