    switch (widget.type) {
      case CommunityReportType.comment:
        return 'تبليغ عن التعليق';
      case CommunityReportType.user:
        return 'تبليغ عن الحساب';
      case CommunityReportType.post:
        return 'تبليغ عن المنشور';
    }
  }

  String get _privacyNote {
    switch (widget.type) {
      case CommunityReportType.comment:
        return 'لن يعرف صاحب التعليق أنك بلّغت';
      case CommunityReportType.user:
        return 'لن يعرف صاحب الحساب أنك بلّغت';
      case CommunityReportType.post:
        return 'لن يعرف صاحب المنشور أنك بلّغت';
    }
  }

  bool get _needsDetails => _selectedId == 'other';
  bool get _showDetails =>
      _selectedId != null &&
          (_needsDetails || _selectedId!.startsWith('academic/'));

  bool get _canSubmit {
    if (_selectedId == null) return false;
    if (_needsDetails && _detailsCtrl.text.trim().isEmpty) return false;
    return true;
  }

  void _submit() {
    if (!_canSubmit) return;
    Navigator.pop(
      context,
      _ReportResult(
        reasonId: _selectedId!,
        details: _detailsCtrl.text.trim(),
      ),
    );
  }

  void _onTapReason(_ReportReason reason) {
    if (reason.isGroup) {
      setState(() {
        _expandedGroupId =
        _expandedGroupId == reason.id ? null : reason.id;
      });
      return;
    }
    setState(() {
      _selectedId = reason.id;
      if (!reason.id.startsWith('academic/')) {
        _expandedGroupId = null;
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return SafeArea(
      child: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              _title,
              textAlign: TextAlign.center,
              style: theme.textTheme.titleMedium?.copyWith(
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              _privacyNote,
              textAlign: TextAlign.center,
              style: theme.textTheme.bodySmall?.copyWith(
                color: theme.hintColor,
              ),
            ),
            const SizedBox(height: 14),
            for (final r in _reasons) ...[
              _reasonTile(theme, r),
              if (r.isGroup && _expandedGroupId == r.id)
                Padding(
                  padding: const EdgeInsetsDirectional.only(start: 18),
                  child: Column(
                    children: [
                      for (final child in r.children)
                        _reasonTile(theme, child, nested: true),
                    ],
                  ),
                ),
            ],
            if (_showDetails) ...[
              const SizedBox(height: 4),
              TextField(
                controller: _detailsCtrl,
                maxLines: 3,
                maxLength: 300,
                onChanged: (_) => setState(() {}),
                decoration: InputDecoration(
                  hintText: _needsDetails
                      ? 'اكتب سبب التبليغ...'
                      : 'تفاصيل إضافية (اختياري)',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
              ),
            ],
            const SizedBox(height: 10),
            FilledButton(
              onPressed: _canSubmit ? _submit : null,
              style: FilledButton.styleFrom(
                backgroundColor: AppTeal.main,
                padding: const EdgeInsets.symmetric(vertical: 14),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(14),
                ),
              ),
              child: const Text(
                'إرسال التبليغ',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _reasonTile(
      ThemeData theme,
      _ReportReason r, {
        bool nested = false,
      }) {
    final selected = _selectedId == r.id;
    final groupOpen = r.isGroup && _expandedGroupId == r.id;
    final groupHasChild = r.isGroup &&
        _selectedId != null &&
        _selectedId!.startsWith('${r.id}/');
    final active = selected || groupHasChild;

    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Material(
        color: active
            ? AppTeal.main.withValues(alpha: 0.12)
            : theme.colorScheme.surfaceContainerHighest.withValues(alpha: 0.45),
        borderRadius: BorderRadius.circular(14),
        child: InkWell(
          borderRadius: BorderRadius.circular(14),
          onTap: () => _onTapReason(r),
          child: Padding(
            padding: EdgeInsets.symmetric(
              horizontal: 12,
              vertical: nested ? 10 : 12,
            ),
            child: Row(
              children: [
                Icon(
                  r.icon,
                  size: nested ? 18 : 20,
                  color: active ? AppTeal.main : theme.hintColor,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    r.label,
                    style: TextStyle(
                      fontWeight: FontWeight.w700,
                      fontSize: nested ? 13.5 : 14.5,
                      color: active
                          ? AppTeal.main
                          : theme.colorScheme.onSurface,
                    ),
                  ),
                ),
                Icon(
                  r.isGroup
                      ? (groupOpen
                      ? Icons.expand_less_rounded
                      : Icons.expand_more_rounded)
                      : (selected
                      ? Icons.radio_button_checked_rounded
                      : Icons.radio_button_off_rounded),
                  size: 20,
                  color: active ? AppTeal.main : theme.hintColor,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}





Future<void> showReportSubmittedSheet(
    BuildContext context, {
      required CommunityReportType type,
      String? ownerId,
      required String ownerName,
      String? ownerPhotoUrl,
      bool useRootNavigator = false,
      bool alreadyReported = false,
      VoidCallback? onBlocked,
      VoidCallback? onUnfollowed,
    }) {
  return showModalBottomSheet<void>(
    context: context,
    useRootNavigator: useRootNavigator,
    isScrollControlled: true,
    showDragHandle: true,
    builder: (ctx) {
      return _ReportSubmittedSheet(
        type: type,
        ownerId: ownerId,
        ownerName: ownerName,
        ownerPhotoUrl: ownerPhotoUrl,
        alreadyReported: alreadyReported,
        onBlocked: onBlocked,
        onUnfollowed: onUnfollowed,
      );
    },
  );
}

class _ReportSubmittedSheet extends StatefulWidget {
  const _ReportSubmittedSheet({
    required this.type,
    required this.ownerName,
    this.ownerId,
    this.ownerPhotoUrl,
    this.alreadyReported = false,
    this.onBlocked,
    this.onUnfollowed,
  });

  final CommunityReportType type;
  final String? ownerId;
  final String ownerName;
  final String? ownerPhotoUrl;
  final bool alreadyReported;
  final VoidCallback? onBlocked;
  final VoidCallback? onUnfollowed;

  @override
  State<_ReportSubmittedSheet> createState() => _ReportSubmittedSheetState();
}

class _ReportSubmittedSheetState extends State<_ReportSubmittedSheet> {
  bool _following = false;
  bool _blocked = false;
  bool _busy = false;

  String get _hiddenHint {
    switch (widget.type) {
      case CommunityReportType.comment:
        return 'أخفينا هذا التعليق عنك.';
      case CommunityReportType.user:
        return 'يمكنك حظر الحساب حتى لا يظهر لك.';
      case CommunityReportType.post:
        return 'أخفينا هذا المنشور عنك.';
    }
  }

  @override
  void initState() {
    super.initState();
    _loadFollow();
  }

  Future<void> _loadFollow() async {
    final me = FirebaseAuth.instance.currentUser?.uid;
    final id = widget.ownerId?.trim();
    if (me == null || id == null || id.isEmpty) return;
    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(me)
          .collection('following')
          .doc(id)
          .get();
      if (!mounted) return;
      setState(() => _following = doc.exists);
    } catch (_) {}
  }

  Future<void> _block() async {
    final id = widget.ownerId?.trim();
    if (id == null || id.isEmpty || _busy) return;
    setState(() => _busy = true);
    try {
      await blockAccount(
        targetId: id,
        targetName: widget.ownerName,
        targetPhotoUrl: widget.ownerPhotoUrl,
      );
      if (!mounted) return;
      setState(() {
        _blocked = true;
        _following = false;
        _busy = false;
      });
      widget.onBlocked?.call();
    } catch (e) {
      debugPrint('post-report block failed: $e');
      if (!mounted) return;
      setState(() => _busy = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر حظر الحساب')),
      );
    }
  }

  Future<void> _unfollow() async {
    final me = FirebaseAuth.instance.currentUser?.uid;
    final id = widget.ownerId?.trim();
    if (me == null || id == null || id.isEmpty || _busy) return;
    setState(() => _busy = true);
    try {
      await setFollowing(
        me: me,
        targetId: id,
        targetName: widget.ownerName,
        targetPhotoUrl: widget.ownerPhotoUrl,
        myName: '',
        follow: false,
      );
      if (!mounted) return;
      setState(() {
        _following = false;
        _busy = false;
      });
      widget.onUnfollowed?.call();
    } catch (e) {
      debugPrint('post-report unfollow failed: $e');
      if (!mounted) return;
      setState(() => _busy = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر إلغاء المتابعة')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final name = widget.ownerName.trim().isEmpty
        ? 'هذا الحساب'
        : widget.ownerName;
    final canAct = widget.ownerId != null &&
        widget.ownerId!.trim().isNotEmpty &&
        !_blocked;

    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 8, 20, 20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.check_circle_rounded, color: AppTeal.main, size: 48),
            const SizedBox(height: 12),
            Text(
              widget.alreadyReported ? 'سبق أن بلّغت' : 'تم إرسال التبليغ',
              style: theme.textTheme.titleMedium?.copyWith(
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              'لن يعرف $name أنك بلّغت. $_hiddenHint',
              textAlign: TextAlign.center,
              style: theme.textTheme.bodySmall?.copyWith(
                color: theme.hintColor,
                height: 1.4,
              ),
            ),
            if (canAct) ...[
              const SizedBox(height: 16),
              SizedBox(
                width: double.infinity,
                child: OutlinedButton.icon(
                  onPressed: _busy ? null : _block,
                  icon: const Icon(Icons.block_rounded, size: 18),
                  label: Text(
                    'حظر $name',
                    style: const TextStyle(fontWeight: FontWeight.w800),
                  ),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: const Color(0xFFDC2626),
                    side: const BorderSide(color: Color(0xFFDC2626)),
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                ),
              ),
              if (_following) ...[
                const SizedBox(height: 8),
                SizedBox(
                  width: double.infinity,
                  child: OutlinedButton(
                    onPressed: _busy ? null : _unfollow,
                    style: OutlinedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14),
                      ),
                    ),
                    child: const Text(
                      'إلغاء المتابعة',
                      style: TextStyle(fontWeight: FontWeight.w800),
                    ),
                  ),
                ),
              ],
            ],
            const SizedBox(height: 10),
            SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: () => Navigator.pop(context),
                style: FilledButton.styleFrom(
                  backgroundColor: AppTeal.main,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
                child: const Text(
                  'تم',
                  style: TextStyle(fontWeight: FontWeight.w800),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}









class BlockedUsersScreen extends StatefulWidget {
  const BlockedUsersScreen({super.key});

  @override
  State<BlockedUsersScreen> createState() => _BlockedUsersScreenState();
}

class _BlockedUsersScreenState extends State<BlockedUsersScreen> {
  final _searchController = TextEditingController();
  final _searchFocus = FocusNode();

  bool _searchOpen = false;
  String _query = '';
  String? _busyId;

  @override
  void dispose() {
    _searchController.dispose();
    _searchFocus.dispose();
    super.dispose();
  }

  CollectionReference<Map<String, dynamic>>? get _col {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return null;
    return FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('blocked_accounts');
  }

  void _toggleSearch() {
    setState(() => _searchOpen = !_searchOpen);
    if (_searchOpen) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _searchFocus.requestFocus();
      });
    } else {
      _searchController.clear();
      _searchFocus.unfocus();
      setState(() => _query = '');
    }
  }

  List<QueryDocumentSnapshot<Map<String, dynamic>>> _prepare(
      List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
      ) {
    final copy = [...docs];
    copy.sort((a, b) {
      final ta = a.data()['blockedAt'];
      final tb = b.data()['blockedAt'];
      if (ta is Timestamp && tb is Timestamp) return tb.compareTo(ta);
      return 0;
    });
    final q = _query.trim().toLowerCase();
    if (q.isEmpty) return copy;
    return copy.where((d) {
      final data = d.data();
      final name = (data['targetName'] ?? '').toString().toLowerCase();
      final user = (data['targetUsername'] ?? '').toString().toLowerCase();
      final id = (data['targetId'] ?? d.id).toString().toLowerCase();
      return name.contains(q) || user.contains(q) || id.contains(q);
    }).toList();
  }

  String _idOf(QueryDocumentSnapshot<Map<String, dynamic>> d) =>
      (d.data()['targetId'] ?? d.id).toString();

  String _nameOf(Map<String, dynamic> data) {
    final n = (data['targetName'] ?? '').toString().trim();
    return n.isEmpty ? 'مستخدم' : n;
  }

  String? _userOf(Map<String, dynamic> data) {
    final u = (data['targetUsername'] ?? '').toString().trim();
    return u.isEmpty ? null : u;
  }

  String? _photoOf(Map<String, dynamic> data) {
    final p = (data['targetPhotoUrl'] ?? '').toString().trim();
    return p.isEmpty ? null : p;
  }

  Future<void> _confirmUnblock({
    required String userId,
    required String name,
  }) async {
    if (_busyId != null) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape:
          RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
          title: const Text(
            'إلغاء الحظر؟',
            style: TextStyle(fontWeight: FontWeight.w800),
          ),
          content: Text(
            'ستظهر منشورات $name في الفيد، ويمكنكما المتابعة مجدداً.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('إلغاء الحظر'),
            ),
          ],
        ),
      ),
    );
    if (ok != true || !mounted) return;

    setState(() => _busyId = userId);
    try {
      await unblockAccount(userId);
      if (!mounted) return;
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(SnackBar(content: Text('تم إلغاء حظر $name')));
    } catch (e) {
      debugPrint('unblock failed: $e');
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر إلغاء الحظر، حاول مجددًا')),
      );
    } finally {
      if (mounted) setState(() => _busyId = null);
    }
  }

  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    final col = _col;

    return Directionality(
      textDirection: TextDirection.rtl,
      child: Scaffold(
        backgroundColor: t.pageBg,
        appBar: AppBar(
          backgroundColor: t.pageBg,
          surfaceTintColor: Colors.transparent,
          elevation: 0,
          titleSpacing: 0,
          title: AnimatedSwitcher(
            duration: const Duration(milliseconds: 180),
            child: _searchOpen
                ? TextField(
              key: const ValueKey('blocked_search'),
              controller: _searchController,
              focusNode: _searchFocus,
              autofocus: true,
              textInputAction: TextInputAction.search,
              onChanged: (v) => setState(() => _query = v),
              decoration: InputDecoration(
                hintText: 'ابحث في المحظورين',
                border: InputBorder.none,
                hintStyle: TextStyle(color: t.textFaint),
              ),
              style: TextStyle(
                color: t.textPrimary,
                fontSize: 16,
                fontWeight: FontWeight.w600,
              ),
            )
                : Text(
              'الحسابات المحظورة',
              key: const ValueKey('blocked_title'),
              style: TextStyle(
                color: t.textPrimary,
                fontWeight: FontWeight.w800,
              ),
            ),
          ),
          actions: [
            IconButton(
              tooltip: _searchOpen ? 'إغلاق' : 'بحث',
              onPressed: _toggleSearch,
              icon: Icon(
                _searchOpen ? Icons.close_rounded : Icons.search_rounded,
                color: t.textPrimary,
              ),
            ),
          ],
        ),
        body: col == null
            ? Center(
          child: Text(
            'سجّل الدخول أولاً',
            style: TextStyle(color: t.textFaint),
          ),
        )
            : StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: col.snapshots(),
          builder: (context, snap) {
            if (snap.hasError) {
              return Center(
                child: Text(
                  'تعذر تحميل القائمة',
                  style: TextStyle(color: t.textFaint),
                ),
              );
            }
            if (!snap.hasData) {
              return const Center(
                child: SizedBox(
                  width: 28,
                  height: 28,
                  child: CircularProgressIndicator(strokeWidth: 2.4),
                ),
              );
            }

            final all = snap.data!.docs;
            final docs = _prepare(all);

            if (all.isEmpty) {
              return Center(
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 40),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(Icons.block_rounded,
                          size: 40, color: t.textFaint),
                      const SizedBox(height: 12),
                      Text(
                        'لا توجد حسابات محظورة',
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          color: t.textPrimary,
                          fontWeight: FontWeight.w800,
                          fontSize: 16,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }

            if (docs.isEmpty) {
              return Center(
                child: Text(
                  'لا نتائج مطابقة',
                  style: TextStyle(color: t.textFaint),
                ),
              );
            }

            return ListView.separated(
              padding: const EdgeInsets.fromLTRB(4, 4, 4, 24),
              itemCount: docs.length,
              separatorBuilder: (_, __) => Divider(
                height: 1,
                indent: 72,
                color: t.cardBorder.withValues(alpha: 0.7),
              ),
              itemBuilder: (context, i) {
                final d = docs[i];
                final data = d.data();
                final id = _idOf(d);
                final name = _nameOf(data);
                return _BlockedUserRow(
                  userId: id,
                  name: name,
                  username: _userOf(data),
                  photoUrl: _photoOf(data),
                  busy: _busyId == id,
                  t: t,
                  onUnblock: () =>
                      _confirmUnblock(userId: id, name: name),
                );
              },
            );
          },
        ),
      ),
    );
  }
}

class _BlockedUserRow extends StatelessWidget {
  const _BlockedUserRow({
    required this.userId,
    required this.name,
    required this.username,
    required this.photoUrl,
    required this.busy,
    required this.t,
    required this.onUnblock,
  });

  final String userId;
  final String name;
  final String? username;
  final String? photoUrl;
  final bool busy;
  final _ProfileTheme t;
  final VoidCallback onUnblock;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;

    return Semantics(
      container: true,
      label: username == null
          ? name
          : '$name، اسم المستخدم $username',
      child: Container(
        margin: const EdgeInsets.symmetric(
          horizontal: 16,
          vertical: 6,
        ),
        decoration: BoxDecoration(
          color: const Color(0xFF1C1C1E),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: t.cardBorder.withOpacity(.75),
            width: 1,
          ),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(.04),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(20),
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: busy ? null : onUnblock,
              splashColor: colorScheme.primary.withOpacity(.06),
              highlightColor: colorScheme.primary.withOpacity(.03),
              child: Padding(
                padding: const EdgeInsetsDirectional.fromSTEB(
                  14,
                  12,
                  12,
                  12,
                ),
                child: Row(

                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    _buildAvatar(),
                    const SizedBox(width: 12),
                    Expanded(
                      child: _buildUserInfo(),
                    ),
                    const SizedBox(width: 10),
                    _buildActionButton(colorScheme),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildAvatar() {
    return Stack(
      alignment: Alignment.bottomRight,
      children: [
        LiveAuthorPhoto(
          userId: userId,
          fallbackUrl: photoUrl,
          size: 48,
          radius: 24,
          iconSize: 22,
        ),
        Container(
          width: 15,
          height: 15,
          decoration: BoxDecoration(
            color: const Color(0xFF1C1C1E),
            shape: BoxShape.circle,
          ),
          padding: const EdgeInsets.all(2),
          child: DecoratedBox(
            decoration: BoxDecoration(
              color: t.textFaint.withOpacity(.65),
              shape: BoxShape.circle,
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildUserInfo() {
    return Directionality(
      textDirection: TextDirection.rtl,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            name.trim().isEmpty ? 'مستخدم' : name,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              color: t.textPrimary,
              fontSize: 15,
              height: 1.2,
              fontWeight: FontWeight.w800,
            ),
          ),
          if (username != null && username!.trim().isNotEmpty) ...[
            const SizedBox(height: 5),
            Text(
              '@${username!.trim()}',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textDirection: TextDirection.ltr,
              style: TextStyle(
                color: t.textFaint,
                fontSize: 12.5,
                height: 1.1,
                fontWeight: FontWeight.w500,
