Future<bool> isPeerUnavailable(String uid) async {
  if (uid.trim().isEmpty) return false;
  try {
    final doc = await FirebaseFirestore.instance
        .collection('users')
        .doc(uid.trim())
        .get();
    return isUserDocUnavailable(doc.data());
  } catch (_) {
    return false;
  }
}

Future<Set<String>> loadUnavailableUserIds(Iterable<String> ids) async {
  final out = <String>{};
  final list = ids
      .map((e) => e.trim())
      .where((e) => e.isNotEmpty)
      .toSet()
      .toList();
  for (var i = 0; i < list.length; i += 10) {
    final end = i + 10 > list.length ? list.length : i + 10;
    final chunk = list.sublist(i, end);
    final snap = await FirebaseFirestore.instance
        .collection('users')
        .where(FieldPath.documentId, whereIn: chunk)
        .get();
    for (final d in snap.docs) {
      if (isUserDocUnavailable(d.data())) out.add(d.id);
    }
  }
  return out;
}

bool isUserDocUnavailable(Map<String, dynamic>? data) {
  final status = data?['accountStatus']?.toString();
  if (status == 'disabled' || status == 'deleted') return true;
  final sec = data?['security'];
  return sec is Map && sec['frozen'] == true;
}


@pragma('vm:entry-point')
Future<void> firebaseMessagingBackgroundHandler(RemoteMessage message) async {
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
}

const _fcmChannel = AndroidNotificationChannel(
  'unispace_notifications',
  'إشعارات UniSpace',
  description: 'متابعة، تعليقات، إعجابات',
  importance: Importance.high,
);

final FlutterLocalNotificationsPlugin _localNotifs =
FlutterLocalNotificationsPlugin();

Future<void> initPushNotifications() async {
  PushPreferencesService.instance.start();
  try {
    final messaging = FirebaseMessaging.instance;

    try {
      await messaging
          .requestPermission(alert: true, badge: true, sound: true)
          .timeout(const Duration(seconds: 8));
    } catch (e) {
      debugPrint('FCM permission: $e');
    }

    await _localNotifs
        .resolvePlatformSpecificImplementation<
        AndroidFlutterLocalNotificationsPlugin>()
        ?.createNotificationChannel(_fcmChannel);

    await _localNotifs.initialize(
      const InitializationSettings(
        android: AndroidInitializationSettings('@mipmap/ic_launcher'),
        iOS: DarwinInitializationSettings(),
      ),
      onDidReceiveNotificationResponse: (res) {
        final payload = res.payload;
        if (payload == null || payload.isEmpty) return;
        _handleFcmPayload(payload);
      },
    );

    // Foreground presentation goes through the local preference check below.
    await messaging.setForegroundNotificationPresentationOptions(
      alert: false,
      badge: false,
      sound: false,
    );

    FirebaseMessaging.onMessage.listen((msg) async {
      if (FirebaseAuth.instance.currentUser == null ||
          (msg.data['recipientId'] != null && msg.data['recipientId'] != FirebaseAuth.instance.currentUser?.uid) ||
          !PushPreferencesService.instance.allows(msg.data['type']?.toString() ?? '')) return;
      final n = msg.notification;
      if (n == null) return;
      await _localNotifs.show(
        msg.hashCode,
        n.title,
        n.body,
        NotificationDetails(
          android: AndroidNotificationDetails(
            _fcmChannel.id,
            _fcmChannel.name,
            channelDescription: _fcmChannel.description,
            importance: Importance.high,
            priority: Priority.high,
            icon: '@mipmap/ic_launcher',
          ),
          iOS: const DarwinNotificationDetails(),
        ),
        payload: jsonEncode(msg.data),
      );
    });

    FirebaseMessaging.onMessageOpenedApp.listen((msg) {
      _openFromFcmData(msg.data);
    });

    try {
      final initial = await messaging
          .getInitialMessage()
          .timeout(const Duration(seconds: 8));
      if (initial != null) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _openFromFcmData(initial.data);
        });
      }
    } catch (e) {
      debugPrint('FCM initial message: $e');
    }

    await saveFcmToken();
    FirebaseMessaging.instance.onTokenRefresh.listen((t) => saveFcmToken(t));
    FirebaseAuth.instance.authStateChanges().listen((user) {
      saveFcmToken();
    });
  } catch (e, st) {
    debugPrint('initPushNotifications failed: $e');
    debugPrintStack(stackTrace: st);
  }
}

final unispaceNavigatorKey = GlobalKey<NavigatorState>();

Future<void> saveFcmToken([String? token]) =>
    PushPreferencesService.instance.sync(token);

void _handleFcmPayload(String payload) {
  try {
    final data = jsonDecode(payload);
    if (data is Map) {
      _openFromFcmData(Map<String, dynamic>.from(data));
    }
  } catch (e) {
    debugPrint('fcm payload parse failed: $e');
  }
}

void _openFromFcmData(Map<String, dynamic> data) {
  final uid = FirebaseAuth.instance.currentUser?.uid;
  if (uid == null || (data['recipientId'] != null && data['recipientId'] != uid)) return;
  final ctx = unispaceNavigatorKey.currentContext;
  if (ctx == null) return;
  final n = NotificationItem(
    id: (data['notificationId'] ?? '').toString(),
    sender: (data['actorName'] ?? 'طالب').toString(),
    message: (data['message'] ?? '').toString(),
    type: (data['type'] ?? 'comment').toString(),
    actorId: data['actorId']?.toString(),
    postId: data['postId']?.toString(),
    commentId: data['commentId']?.toString(),
    read: false,
  );
  _openNotification(ctx, n);
}

class HiddenPostsScreen extends StatefulWidget {
  const HiddenPostsScreen({super.key});

  @override
  State<HiddenPostsScreen> createState() => _HiddenPostsScreenState();
}

class _HiddenPostsScreenState extends State<HiddenPostsScreen>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;
  int _postsGeneration = 0, _commentsGeneration = 0;
  String? _uid;
  StreamSubscription<User?>? _auth;
  bool _current(String uid, int generation, bool comments) => mounted &&
      FirebaseAuth.instance.currentUser?.uid == uid &&
      generation == (comments ? _commentsGeneration : _postsGeneration);
  void _refreshAccess() { if (mounted) { _loadPosts(); _loadComments(); } }

  Future<Map<String, _Post>> _readHiddenPostContent(
    Iterable<String> input, String uid, int generation, bool comments,
  ) async {
    final ids = input.map((id) => id.trim()).where((id) => id.isNotEmpty).toSet().toList();
    final posts = <String, _Post>{};
    for (var i = 0; i < ids.length; i += 5) {
      if (!_current(uid, generation, comments)) return {};
      final end = i + 5 < ids.length ? i + 5 : ids.length;
      await Future.wait(ids.sublist(i, end).map((id) async {
        try {
          final data = await _readAuthorizedPostData(id);
          if (_current(uid, generation, comments)) posts[id] = _Post.fromData(id, data);
        } on FirebaseFunctionsException catch (error) {
          if (error.code != 'not-found') rethrow;
        }
      }));
    }
    return posts;
  }

  // ===== منشورات =====
  bool _loadingPosts = true;
  String? _postsError;
  List<_Post> _posts = [];

  // ===== تعليقات =====
  bool _loadingComments = true;
  String? _commentsError;
  List<_CommentSearchHit> _hiddenComments = [];

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    _uid = FirebaseAuth.instance.currentUser?.uid;
    _auth = FirebaseAuth.instance.authStateChanges().listen((user) {
      if (!mounted || user?.uid == _uid) return;
      _uid = user?.uid;
      _refreshAccess();
    });
    blockedListRevision.addListener(_refreshAccess);
    hiddenListRevision.addListener(_refreshAccess);
    authorProfileRevision.addListener(_refreshAccess);
    moderationRevision.addListener(_refreshAccess);
    _refreshAccess();
  }

  @override
  void dispose() {
    _postsGeneration++; _commentsGeneration++;
    _auth?.cancel();
    blockedListRevision.removeListener(_refreshAccess);
    hiddenListRevision.removeListener(_refreshAccess);
    authorProfileRevision.removeListener(_refreshAccess);
    moderationRevision.removeListener(_refreshAccess);
    _tabController.dispose();
    super.dispose();
  }

  // ---------------------------------------------------------------------
  // منشورات
  // ---------------------------------------------------------------------
  Future<void> _loadPosts() async {
    if (!mounted) return;
    final generation = ++_postsGeneration;
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) {
      setState(() {
        _posts = [];
        _loadingPosts = false;
        _postsError = 'يجب تسجيل الدخول أولاً';
      });
      return;
    }
    setState(() {
      _posts = [];
      _loadingPosts = true;
      _postsError = null;
    });
    try {
      final hiddenSnap = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('hidden_posts')
          .get();
      final ids = hiddenSnap.docs.map((d) => d.id).toList();
      if (ids.isEmpty) {
        if (!_current(uid, generation, false)) return;
        setState(() {
          _posts = [];
          _loadingPosts = false;
        });
        return;
      }

      final authorized = await _readHiddenPostContent(ids, uid, generation, false);
      final posts = authorized.values.toList();
      if (!_current(uid, generation, false)) return;
      setState(() {
        _posts = posts;
        _loadingPosts = false;
      });
    } catch (e) {
      debugPrint('load hidden posts failed: $e');
      if (!_current(uid, generation, false)) return;
      setState(() {
        _loadingPosts = false;
        _postsError = 'تعذر تحميل المنشورات المخفية';
      });
    }
  }

  Future<void> _unhidePost(String postId) async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;
    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('hidden_posts')
          .doc(postId)
          .delete();
      if (!mounted || FirebaseAuth.instance.currentUser?.uid != uid) return;
      setState(() => _posts.removeWhere((p) => p.id == postId));
      hiddenListRevision.value++;
    } catch (e) {
      debugPrint('unhide post failed: $e');
    }
  }

  // ---------------------------------------------------------------------
  // تعليقات
  // ---------------------------------------------------------------------
  Future<void> _loadComments() async {
    if (!mounted) return;
    final generation = ++_commentsGeneration;
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) {
      setState(() {
        _hiddenComments = [];
        _loadingComments = false;
        _commentsError = 'يجب تسجيل الدخول أولاً';
      });
      return;
    }
    setState(() {
      _hiddenComments = [];
      _loadingComments = true;
      _commentsError = null;
    });
    try {
      final hiddenSnap = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('hidden_comments')
          .get();

      final Map<String, List<String>> byPost = {};
      for (final d in hiddenSnap.docs) {
        final data = d.data();
        final postId = (data['postId'] ?? '').toString();
        final commentId = (data['commentId'] ?? d.id).toString();
        if (postId.isEmpty || commentId.isEmpty) continue;
        byPost.putIfAbsent(postId, () => []).add(commentId);
      }

      if (byPost.isEmpty) {
        if (!_current(uid, generation, true)) return;
        setState(() {
          _hiddenComments = [];
          _loadingComments = false;
        });
        return;
      }

      final posts = await _readHiddenPostContent(byPost.keys, uid, generation, true);
      if (!_current(uid, generation, true)) return;

      _Comment? find(_Comment c, String id) {
        if (c.id == id) return c;
        for (final r in c.replies) {
          final f = find(r, id);
          if (f != null) return f;
        }
        return null;
      }

      final hits = <_CommentSearchHit>[];
      byPost.forEach((postId, commentIds) {
        final post = posts[postId];
        if (post == null) return;
        for (final cid in commentIds) {
          _Comment? found;
          for (final c in post.comments) {
            found = find(c, cid);
            if (found != null) break;
          }
          if (found != null) {
            hits.add(_CommentSearchHit(post: post, comment: found));
          }
        }
      });

      if (!_current(uid, generation, true)) return;
      setState(() {
        _hiddenComments = hits;
        _loadingComments = false;
      });
    } catch (e) {
      debugPrint('load hidden comments failed: $e');
      if (!_current(uid, generation, true)) return;
      setState(() {
        _loadingComments = false;
        _commentsError = 'تعذر تحميل التعليقات المخفية';
      });
    }
  }

  Future<void> _unhideComment(String commentId) async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;
    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('hidden_comments')
          .doc(commentId)
          .delete();
      if (!mounted || FirebaseAuth.instance.currentUser?.uid != uid) return;
      setState(() =>
          _hiddenComments.removeWhere((h) => h.comment.id == commentId));
      hiddenListRevision.value++;
    } catch (e) {
      debugPrint('unhide comment failed: $e');
    }
  }

  // ---------------------------------------------------------------------
  // UI
  // ---------------------------------------------------------------------
  @override
  Widget build(BuildContext context) {
    final t = _ProfileTheme.of(context);
    return Scaffold(
      backgroundColor: t.pageBg,
      appBar: AppBar(
        title: const Text('العناصر المخفية'),
        backgroundColor: t.pageBg,
        surfaceTintColor: Colors.transparent,
        bottom: TabBar(
          controller: _tabController,
          labelColor: t.textPrimary,
          unselectedLabelColor: t.textFaint,
          indicatorColor: AppTeal.main,
          tabs: const [
            Tab(text: 'منشورات'),
            Tab(text: 'تعليقات'),
          ],
        ),
      ),
      body: TabBarView(
        controller: _tabController,
        children: [
          _buildPostsTab(),
          _buildCommentsTab(),
        ],
      ),
    );
  }

  Widget _buildPostsTab() {
    return RefreshIndicator(
      onRefresh: _loadPosts,
      child: _loadingPosts
          ? const Center(child: CircularProgressIndicator())
          : _postsError != null
          ? ListView(
        children: [
          const SizedBox(height: 80),
          Center(child: Text(_postsError!)),
          TextButton(onPressed: _loadPosts, child: const Text('إعادة المحاولة')),
        ],
      )
          : _posts.isEmpty
          ? ListView(
        children: const [
          SizedBox(height: 80),
          EmptyState(
            icon: Icons.visibility_off_outlined,
            title: 'لا توجد منشورات مخفية',
          ),
        ],
      )
          : ListView.separated(
        padding: const EdgeInsets.fromLTRB(12, 8, 12, 24),
        itemCount: _posts.length,
        separatorBuilder: (_, __) => const SizedBox(height: 8),
        itemBuilder: (context, i) {
          final p = _posts[i];
          return Stack(
            clipBehavior: Clip.none,
            children: [
              _RedditStylePostCard(
                post: p,
                accent: Theme.of(context).colorScheme.primary,
              ),
              Positioned(
                top: 8,
                right: 8,
                child: Material(
                  color: Colors.black.withValues(alpha: 0.55),
                  shape: const CircleBorder(),
                  child: InkWell(
                    customBorder: const CircleBorder(),
                    onTap: p.id == null ? null : () => _unhidePost(p.id!),
                    child: const Padding(
                      padding: EdgeInsets.all(6),
                      child: Icon(
                        Icons.visibility_off_rounded,
                        color: Colors.white,
                        size: 18,
                      ),
                    ),
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildCommentsTab() {
    return RefreshIndicator(
      onRefresh: _loadComments,
      child: _loadingComments
          ? const Center(child: CircularProgressIndicator())
          : _commentsError != null
          ? ListView(
        children: [
          const SizedBox(height: 80),
          Center(child: Text(_commentsError!)),
          TextButton(onPressed: _loadComments, child: const Text('إعادة المحاولة')),
        ],
      )
          : _hiddenComments.isEmpty
          ? ListView(
        children: const [
          SizedBox(height: 80),
          EmptyState(
            icon: Icons.visibility_off_outlined,
            title: 'لا توجد تعليقات مخفية',
          ),
        ],
      )
          : ListView.separated(
        padding: const EdgeInsets.fromLTRB(12, 8, 12, 24),
        itemCount: _hiddenComments.length,
        separatorBuilder: (_, __) => const SizedBox(height: 8),
        itemBuilder: (context, i) {
          final hit = _hiddenComments[i];
          return Stack(
            clipBehavior: Clip.none,
            children: [
              _RedditStyleCommentTile(
                hit: hit,
                accent: Theme.of(context).colorScheme.primary,
              ),
              Positioned(
                top: 8,
                right: 8,
                child: Material(
                  color: Colors.black.withValues(alpha: 0.55),
                  shape: const CircleBorder(),
                  child: InkWell(
                    customBorder: const CircleBorder(),
                    onTap: () => _unhideComment(hit.comment.id),
                    child: const Padding(
                      padding: EdgeInsets.all(6),
                      child: Icon(
                        Icons.visibility_off_rounded,
                        color: Colors.white,
                        size: 18,
                      ),
                    ),
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}


final moderationRevision = ValueNotifier<int>(0);

class CommunityReportsInboxScreen extends StatefulWidget {
  const CommunityReportsInboxScreen({super.key});

  @override
  State<CommunityReportsInboxScreen> createState() =>
      _CommunityReportsInboxScreenState();
}

class _ModerationInboxRow {
  const _ModerationInboxRow(this.id, this._data);
  final String id;
  final Map<String, dynamic> _data;
  Map<String, dynamic> data() => _data;
}

dynamic _decodeReportValue(dynamic value) {
  if (value is List) return value.map(_decodeReportValue).toList();
  if (value is Map) {
    if (value.length == 1 && value['__reportTime'] is num) {
      return Timestamp.fromMillisecondsSinceEpoch((value['__reportTime'] as num).toInt());
    }
    return value.map((k,v) => MapEntry(k.toString(), _decodeReportValue(v)));
  }
  return value;
}

class _CommunityReportsInboxScreenState
    extends State<CommunityReportsInboxScreen> {
  String _filter = 'pending';
  String _search = '';
  final TextEditingController _searchCtrl = TextEditingController();

  // ===== عدّادات سريعة لكل حالة (لعرضها فالرأس) =====
  Map<String, int> _counts = {
    'pending': 0,
    'actioned': 0,
    'dismissed': 0,
    'restored': 0,
  };

  StreamSubscription<User?>? _authSub;
  final List<_ModerationInboxRow> _reports = [];
  bool _loading = false, _exhausted = false;
  String? _cursor, _loadError;
  int _loadGeneration = 0;

  @override
  void initState() {
    super.initState();
    _authSub = FirebaseAuth.instance.authStateChanges().listen((_) => _loadReports());
    _loadReports();
  }

  @override
  void dispose() {
    _loadGeneration++;
    _authSub?.cancel();
    _searchCtrl.dispose();
    super.dispose();
  }

  void _selectFilter(String value) {
    setState(() => _filter = value);
    _loadReports();
  }

  Future<void> _loadReports({bool more = false}) async {
    if (more && (_loading || _exhausted)) return;
    final generation = ++_loadGeneration;
    final uid = FirebaseAuth.instance.currentUser?.uid;
    setState(() {
      _loading = true; _loadError = null;
      if (!more) { _reports.clear(); _cursor = null; _exhausted = false; _counts.updateAll((_, __) => 0); }
    });
    try {
      if (uid == null) throw StateError('Signed out');
      final response = await FirebaseFunctions.instanceFor(region: 'europe-west1')
          .httpsCallable('readModerationInbox')
          .call({'status': _filter, 'cursor': _cursor});
      if (!mounted || generation != _loadGeneration || FirebaseAuth.instance.currentUser?.uid != uid) return;
      final result = Map<String, dynamic>.from(response.data as Map);
      final rows = (result['reports'] as List).map((v) {
        final row = Map<String, dynamic>.from(v as Map);
        return _ModerationInboxRow(row['id'] as String,
            Map<String, dynamic>.from(_decodeReportValue(row['data']) as Map));
      }).toList();
      setState(() {
        for (final row in rows) {
          _reports.removeWhere((old) => old.id == row.id);
          _reports.add(row);
        }
        _counts = Map<String, dynamic>.from(result['counts'] as Map).map((k,v) => MapEntry(k,(v as num).toInt()));
        _cursor = result['cursor'] as String?;
        _exhausted = result['exhausted'] == true;
      });
    } catch (_) {
      if (!mounted || generation != _loadGeneration) return;
      setState(() { _reports.clear(); _counts.updateAll((_, __) => 0); _cursor = null;
        _loadError = 'تعذر تحميل البلاغات أو لم تعد لديك صلاحية الوصول'; });
    } finally {
      if (mounted && generation == _loadGeneration) setState(() => _loading = false);
    }
  }

  String _typeLabel(String type) {
    switch (type) {
      case 'comment':
        return 'تعليق';
      case 'user':
        return 'حساب';
      default:
        return 'منشور';
    }
  }

  String _reasonLabel(String id) {
    switch (id) {
      case 'academic/exam_leak':
        return 'تسريب امتحان أو فرض';
      case 'academic/cheating':
        return 'غش أو بيع حلول';
      case 'academic/misinfo':
        return 'معلومات دراسية مضللة';
      case 'abuse':
        return 'إساءة أو تنمّر';
      case 'sexual':
        return 'محتوى غير لائق';
      case 'spam':
        return 'إعلان أو سبام';
      case 'impersonation':
        return 'انتحال شخصية';
      case 'hate':
        return 'خطاب كراهية';
      case 'harassment':
        return 'مضايقة';
      case 'fake':
        return 'حساب وهمي';
      case 'inappropriate_profile':
        return 'معلومات غير لائقة';
      case 'other':
        return 'أخرى';
      default:
        return id;
    }
  }

  String _statusLabel(String status) {
    switch (status) {
      case 'actioned':
        return 'مخفي';
      case 'dismissed':
        return 'مرفوض';
      case 'restored':
        return 'مستعاد';
      default:
        return 'معلّق';
    }
  }

  Color _statusColor(String status) {
    switch (status) {
      case 'actioned':
        return const Color(0xFFDC2626);
      case 'dismissed':
        return const Color(0xFF64748B);
      case 'restored':
        return const Color(0xFF16A34A);
      default:
        return AppTeal.main;
    }
  }

  Color _severityColor(String sev) {
    switch (sev) {
      case 'P1':
        return const Color(0xFFDC2626);
      case 'P2':
        return const Color(0xFFF59E0B);
      default:
        return const Color(0xFF64748B);
    }
  }

  String _emptyLabel() {
    switch (_filter) {
      case 'actioned':
        return 'لا يوجد محتوى مخفي';
      case 'dismissed':
        return 'لا توجد تبليغات مرفوضة';
      case 'restored':
        return 'لا توجد محتويات مستعادة';
      default:
        return 'لا توجد تبليغات معلّقة حاليًا 🎉';
    }
  }

  IconData _emptyIcon() {
    switch (_filter) {
      case 'actioned':
        return Icons.visibility_off_outlined;
      case 'dismissed':
        return Icons.block_flipped;
      case 'restored':
        return Icons.restore_rounded;
      default:
        return Icons.task_alt_rounded;
    }
  }

  void _toast(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(msg),
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        margin: const EdgeInsets.all(14),
      ),
    );
  }
  bool _moderationBusy = false;
  Future<void> _moderateReport(
      _ModerationInboxRow doc,
      String action, String successMessage) async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (_moderationBusy || uid == null) return;
    _moderationBusy = true;
    try {
      await FirebaseFunctions.instanceFor(region: 'europe-west1')
          .httpsCallable('moderateCommunityReport')
          .call({
            'reportId': doc.id,
            'action': action,
            'expectedStatus': (doc.data()['status'] ?? 'pending').toString(),
          });
      if (!mounted || FirebaseAuth.instance.currentUser?.uid != uid) return;
      moderationRevision.value++;
      _toast(successMessage);
      await _loadReports();
    } catch (e) {
      if (!mounted || FirebaseAuth.instance.currentUser?.uid != uid) return;
      _toast(e is FirebaseFunctionsException && e.code == 'failed-precondition'
          ? 'تغيّرت حالة البلاغ أو تعذر تنفيذ الإجراء؛ افتح البلاغ مجدداً'
          : 'تعذر تنفيذ إجراء الإشراف');
    } finally {
      _moderationBusy = false;
    }
  }

  Future<void> _reopen(_ModerationInboxRow doc) =>
      _moderateReport(doc, 'reopen', 'أُعيد فتح التبليغ');

  Future<void> _dismiss(_ModerationInboxRow doc) =>
      _moderateReport(doc, 'dismiss', 'تم رفض التبليغ');

  Future<void> _restore(_ModerationInboxRow doc) =>
      _moderateReport(doc, 'restore', 'تمت استعادة المحتوى');

  Future<void> _action(_ModerationInboxRow doc) =>
      _moderateReport(doc, 'hide', doc.data()['type'] == 'comment'
          ? 'تم إخفاء التعليق للجميع' : 'تم إخفاء المنشور للجميع');

  Future<void> _openSheet(
      _ModerationInboxRow d,
      Map<String, dynamic> data,
      ) async {
    final type = data['type']?.toString() ?? 'post';
    final reason = data['reason']?.toString() ?? '';
    final owner = data['ownerName']?.toString() ?? '';
    final status = data['status']?.toString() ?? 'pending';
    final snapMap = data['snapshot'];
    String preview = '';
    if (snapMap is Map) {
      preview = (snapMap['body'] ??
          snapMap['text'] ??
          snapMap['title'] ??
          snapMap['displayName'] ??
          '')
          .toString();
    }

    final action = await showModalBottomSheet<String>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(22)),
      ),
      builder: (ctx) {
        return SafeArea(
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(18, 4, 18, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    _StatusChip(label: _statusLabel(status), color: _statusColor(status)),
                    const SizedBox(width: 8),
                    Text(
                      _typeLabel(type),
                      style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 13),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                Text(
                  _reasonLabel(reason),
                  style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 17),
                ),
                if (owner.isNotEmpty) ...[
                  const SizedBox(height: 6),
                  Row(
                    children: [
                      Icon(Icons.person_outline_rounded, size: 16, color: Theme.of(ctx).hintColor),
                      const SizedBox(width: 4),
                      Text('صاحب المحتوى: $owner'),
                    ],
                  ),
                ],
                if ((data['details'] ?? '').toString().trim().isNotEmpty) ...[
                  const SizedBox(height: 10),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: Theme.of(ctx).colorScheme.surfaceContainerHighest.withValues(alpha: 0.4),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: Text('تفاصيل المُبلِّغ: ${data['details']}'),
                  ),
                ],
                if (preview.isNotEmpty) ...[
                  const SizedBox(height: 10),
                  Text(
                    preview,
                    maxLines: 5,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(color: Theme.of(ctx).hintColor, height: 1.4),
                  ),
                ],
                const SizedBox(height: 20),
                if (status == 'pending' && (type == 'post' || type == 'comment'))
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton.icon(
                      onPressed: () => Navigator.pop(ctx, 'remove'),
                      icon: const Icon(Icons.visibility_off_rounded, size: 18),
                      label: const Text('إخفاء للجميع'),
                      style: FilledButton.styleFrom(
                        backgroundColor: const Color(0xFFDC2626),
                        padding: const EdgeInsets.symmetric(vertical: 13),
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      ),
                    ),
                  ),
                if (status == 'pending') ...[
                  const SizedBox(height: 8),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton.icon(
                      onPressed: () => Navigator.pop(ctx, 'dismiss'),
                      icon: const Icon(Icons.close_rounded, size: 18),
                      label: const Text('رفض التبليغ'),
                      style: OutlinedButton.styleFrom(
                        padding: const EdgeInsets.symmetric(vertical: 13),
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      ),
                    ),
                  ),
                ],
                if (status == 'actioned')
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton.icon(
                      onPressed: () => Navigator.pop(ctx, 'restore'),
                      icon: const Icon(Icons.restore_rounded, size: 18),
                      label: const Text('استعادة المحتوى'),
                      style: FilledButton.styleFrom(
                        backgroundColor: const Color(0xFF16A34A),
                        padding: const EdgeInsets.symmetric(vertical: 13),
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      ),
                    ),
                  ),
                if (status == 'dismissed' || status == 'restored') ...[
                  const SizedBox(height: 8),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton.icon(
                      onPressed: () => Navigator.pop(ctx, 'reopen'),
                      icon: const Icon(Icons.replay_rounded, size: 18),
                      label: const Text('تراجع: إعادة فتح التبليغ'),
                    ),
                  ),
                ],
              ],
            ),
          ),
        );
      },
    );

    if (action == 'dismiss') {
      await _dismiss(d);
    } else if (action == 'remove') {
      await _action(d);
    } else if (action == 'restore') {
      await _restore(d);
    } else if (action == 'reopen') {
  await _reopen(d);
  }
  }

  @override
  Widget build(BuildContext context) {
    if (!isCommunityModerator()) {
      return const Scaffold(
        body: Center(child: Text('غير مصرّح')),
      );
    }

    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    return Scaffold(
      backgroundColor: theme.scaffoldBackgroundColor,
      appBar: AppBar(
        title: const Text('مراجعة التبليغات', style: TextStyle(fontWeight: FontWeight.w800)),
        actions: [IconButton(onPressed: () => _loadReports(), tooltip: 'تحديث', icon: const Icon(Icons.refresh))],
        elevation: 0,
        scrolledUnderElevation: 0.5,
      ),
      body: Column(
        children: [
          // ===== شريط إحصائيات سريعة =====
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 10, 14, 4),
            child: Row(
              children: [
                _StatChip(
                  label: 'معلّق',
                  count: _counts['pending'] ?? 0,
                  color: AppTeal.main,
                  icon: Icons.hourglass_top_rounded,
                ),
                const SizedBox(width: 8),
                _StatChip(
                  label: 'مخفي',
                  count: _counts['actioned'] ?? 0,
                  color: const Color(0xFFDC2626),
                  icon: Icons.visibility_off_rounded,
                ),
                const SizedBox(width: 8),
                _StatChip(
                  label: 'مرفوض',
                  count: _counts['dismissed'] ?? 0,
                  color: const Color(0xFF64748B),
                  icon: Icons.block_flipped,
                ),
              ],
            ),
          ),

          // ===== فلاتر بشكل كبسولات =====
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 8),
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: Row(
                children: [
                  _FilterPill(
                    label: 'معلّق',
                    value: 'pending',
                    selected: _filter == 'pending',
                    count: _counts['pending'] ?? 0,
                    color: AppTeal.main,
                    onTap: () => _selectFilter('pending'),
                  ),
                  const SizedBox(width: 8),
                  _FilterPill(
                    label: 'مخفي',
                    value: 'actioned',
                    selected: _filter == 'actioned',
                    count: _counts['actioned'] ?? 0,
                    color: const Color(0xFFDC2626),
                    onTap: () => _selectFilter('actioned'),
                  ),
                  const SizedBox(width: 8),
                  _FilterPill(
                    label: 'مرفوض',
                    value: 'dismissed',
                    selected: _filter == 'dismissed',
                    count: _counts['dismissed'] ?? 0,
                    color: const Color(0xFF64748B),
                    onTap: () => _selectFilter('dismissed'),
                  ),
                  const SizedBox(width: 8),
                  _FilterPill(
                    label: 'مستعاد',
                    value: 'restored',
                    selected: _filter == 'restored',
                    count: _counts['restored'] ?? 0,
                    color: const Color(0xFF16A34A),
                    onTap: () => _selectFilter('restored'),
                  ),
                ],
              ),
            ),
          ),

          // ===== حقل بحث بسيط باسم صاحب المحتوى =====
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 0, 14, 8),
            child: TextField(
              controller: _searchCtrl,
              onChanged: (v) => setState(() => _search = v.trim().toLowerCase()),
              style: const TextStyle(fontSize: 13.5),
              decoration: InputDecoration(
                hintText: 'ابحث في البلاغات المحمّلة باسم صاحب المحتوى...',
                hintStyle: TextStyle(fontSize: 13, color: theme.hintColor),
                prefixIcon: Icon(Icons.search_rounded, size: 20, color: theme.hintColor),
                suffixIcon: _search.isEmpty
                    ? null
                    : IconButton(
                  icon: const Icon(Icons.close_rounded, size: 18),
                  onPressed: () {
                    _searchCtrl.clear();
                    setState(() => _search = '');
                  },
                ),
                filled: true,
                fillColor: isDark
                    ? Colors.white.withValues(alpha: 0.06)
                    : Colors.black.withValues(alpha: 0.04),
                isDense: true,
                contentPadding: const EdgeInsets.symmetric(vertical: 10),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(14),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
          ),

          Expanded(
            child: Builder(
              builder: (context) {
                if (_loadError != null) {
                  return Center(child: TextButton(onPressed: () => _loadReports(), child: Text(_loadError! + ' — إعادة المحاولة')));
                }
                if (_loading && _reports.isEmpty) return const Center(child: CircularProgressIndicator());
                var docs = [..._reports];

                if (_search.isNotEmpty) {
                  docs = docs.where((d) {
                    final owner = (d.data()['ownerName'] ?? '').toString().toLowerCase();
                    return owner.contains(_search);
                  }).toList();
                }

                docs.sort((a, b) {
                  const order = {'P1': 0, 'P2': 1, 'P3': 2};
                  final sa = order[a.data()['severity']?.toString()] ?? 9;
                  final sb = order[b.data()['severity']?.toString()] ?? 9;
                  if (sa != sb) return sa.compareTo(sb);
                  final ta = a.data()['createdAt'];
                  final tb = b.data()['createdAt'];
                  if (ta is Timestamp && tb is Timestamp) return tb.compareTo(ta);
                  return 0;
                });

                if (docs.isEmpty) {
                  return _EmptyModerationState(
                    icon: _emptyIcon(),
                    label: _emptyLabel(),
                  );
                }

                return ListView.separated(
                  padding: const EdgeInsets.fromLTRB(12, 4, 12, 24),
                  itemCount: docs.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 10),
                  itemBuilder: (context, i) {
                    final d = docs[i];
                    final data = d.data();
                    final type = data['type']?.toString() ?? 'post';
                    final reason = data['reason']?.toString() ?? '';
                    final status = data['status']?.toString() ?? 'pending';
                    final severity = data['severity']?.toString() ?? 'P3';

                    return _ModerationReportCard(
                      key: ValueKey(d.id),
                      reportId: d.id,
                      data: data,
                      severityColor: _severityColor(severity),
                      severityLabel: severity,
                      statusLabel: _statusLabel(status),
                      statusColor: _statusColor(status),
                      reasonLabel: _reasonLabel(reason),
                      typeLabel: _typeLabel(type),
                      onReview: () => _openSheet(d, data),
                      onQuickDismiss: status == 'pending' ? () => _dismiss(d) : null,
                      onQuickAction:
                      status == 'pending' && type != 'user' ? () => _action(d) : null,
                    );
                  },
                );
              },
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(8),
            child: Column(children: [
              const Text('البحث وترتيب الأولوية ضمن البلاغات المحمّلة', style: TextStyle(fontSize: 12)),
              if (!_exhausted && _loadError == null)
                TextButton(onPressed: _loading ? null : () => _loadReports(more: true),
                    child: Text(_loading ? 'جارٍ التحميل...' : 'تحميل المزيد')),
            ]),
          ),
        ],
      ),
    );
  }
}

